INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a7acae16abfccbf50b1e52e', 'paytm', 'Paytm', 'Paytm', '2025-01-01', 'Talented', 'Roopali Singhal', NULL, NULL, 'digital film', NULL, NULL, '["fintech", "digital payments"]', NULL, NULL, '[]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference point for consumer fintech and digital payments work made with an agency team, where the pitch is a single film rather than a series. The credit sheet points to a conventional advertising shape: a line produced shoot backed by a full producer and post chain, with original music, a mix, grade and online finish, so it suits briefs that need a polished broadcast and social cut. Content, cast and locations are not described in the available sources, so treat it as a production shape and craft reference rather than a story or tone match.', 0, 0, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b868eee3b1cb44b9332f', 'schweppes-x-jazzy-b', 'Schweppes', 'Schweppes x Jazzy B', '2024-11-15', NULL, 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=wQHdPuntoXg', 'TVC', 30, 'Punjabi', '["Beverages", "Food and beverage"]', 'brand film', 'Celebrity musician fronts a music-led film built around an original track and a catchy hook line, with the drink and quick-commerce delivery woven into the performance', '["playful", "high energy", "swagger", "pop culture"]', 'Jazzy B', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a short celebrity-fronted beverage film where the whole idea rides on music rather than dialogue. The script hangs on a Punjabi music star performing an original track, with a repeated hook line carrying the brand message and a quick-commerce delivery beat folded into the action. Production shape is a performance-led shoot around one artist, so the spend sits in talent, a bespoke music track, styling and choreography rather than location count. Tone is playful, high energy and full of pop-culture swagger, pitched at a regional audience while staying premium in look. Good comparison for thirty second music-video-style brand work.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b868eee3b1cb44b9332d', 'pokerbaazi-x-shahid-kapoor-leave-application', 'PokerBaazi', 'PokerBaazi x Shahid Kapoor: Leave Application', '2024-05-15', 'Talented', NULL, NULL, 'https://www.youtube.com/watch?v=xGqeX-uV8qc', 'TVC', 30, 'Hindi', '["Media, broadcast & entertainment", "Gaming", "Online gaming"]', 'other', 'An everyday office exchange where a leave application becomes a bluff-read, translating poker instinct into a mundane situation', '["witty", "deadpan", "observational", "mainstream"]', 'Shahid Kapoor', 'complex', '["vfx"]', '[]', NULL, 'A useful reference for a short celebrity led category film that sells a skill game positioning through everyday behaviour rather than gameplay. The script takes an ordinary office moment, a staffer asking for leave, and plays it as a bluff being read, so the comedy sits in restraint, timing and glances instead of dialogue heavy setup. Production shape is a contained interior set with a designed workplace, a small supporting cast, a star with a full entourage and body double, plus a robotic arm rig for precise repeatable moves and light CG cleanup in post. Tone is dry, confident and mainstream, and it belongs to a three film set so casting and set design carry across.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b868eee3b1cb44b9332b', 'pokerbaazi-x-shahid-kapoor-elevator-pitch', 'PokerBaazi', 'PokerBaazi x Shahid Kapoor: Elevator Pitch', '2024-05-15', 'Talented', NULL, NULL, 'https://www.youtube.com/watch?v=KxigQy1ZbBM', 'TVC', 30, 'Hindi', '["Media, broadcast & entertainment", "Online gaming"]', 'brand film', 'Everyday situation reframed as a poker read, with a deadpan comic scenario played straight in an elevator', '["deadpan", "comic", "dry", "understated"]', 'Shahid Kapoor', 'complex', '[]', '[]', NULL, 'A useful reference for short, sharply written celebrity comedy where a skill based gaming brand borrows poker instinct and drops it into an ordinary situation. The script here is built on a single confined setting, a lift, a small supporting cast and one film star carried by timing rather than dialogue volume, with the humour played completely straight. Production shape is contained but star led, involving entourage coordination, casting, styling, a designed interior set and a robotic arm rig for precise camera moves. Good comparison for thirty second brand spots that sit inside a multi film series and need mainstream entertainment appeal with a dry, restrained tone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b868eee3b1cb44b93329', 'pokerbaazi-x-shahid-kapoor-suspect', 'PokerBaazi', 'PokerBaazi x Shahid Kapoor: Suspect', '2024-05-15', 'Talented', NULL, NULL, 'https://www.youtube.com/watch?v=U51firevrWI', 'TVC', 30, NULL, '["Media, broadcast & entertainment", "Online gaming"]', 'brand film', 'Celebrity-led everyday scenario where poker instincts are used to read people in an ordinary situation, played as an observational vignette', '["wry", "deadpan", "confident", "humorous"]', 'Shahid Kapoor', 'complex', '["vfx"]', '[]', NULL, 'A useful reference for a short celebrity-fronted brand spot that dramatises a product idea through an everyday social situation, in this case reading people the way a player reads a table. The script shape is a single contained scenario with a turn at the end, carried by one lead actor plus a small supporting ensemble, so casting and performance timing matter more than scale. Production shape involves a designed interior set, a robotic arm rig for precise repeatable camera moves, a star entourage to schedule around, and light CG cleanup in post. Tone is dry, confident and lightly comic, and it sits within a three-film package built on the same device.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b36e59e34184ae1fb886', 'google-search-something-new', 'Google', 'Search Something New', '2024-06-30', 'Talented', 'Shiv Parameswaran', 'shiv-parameswaran', 'https://www.youtube.com/watch?v=rwWg9Zw4f-c', 'series', 20, 'Hindi', '["Consumer Technology", "Search and Internet"]', 'brand film', 'Rhythmic, associative editing that jumps from one curiosity-led discovery to the next, each short film built around a familiar Indian visual cue such as a black and yellow taxi, a matchbox or a truck slogan', '["playful", "curious", "fast-paced", "quirky"]', NULL, 'complex', '["vfx", "vehicle", "music_led"]', '["Google: Search Something New | Kyoorius Creative Awards 2024 (Baby Blue Elephant)"]', 'Kyoorius Creative Awards 2024: Baby Blue Elephant, Film Craft (Editing)', 'A useful reference for a short form tech or search brand campaign built as a set of four twenty second films rather than one long story, where the idea lives in the cut. The device is rhythmic associative editing that leaps between everyday Indian sights and the questions they spark, so the shape is many small setups, a compact cast of two actors, art directed props and vehicle work, styling and design detail in every frame, plus CG support, grade and an original music and voice over track to carry the pace. Tone is playful, curious and quick witted, and the craft demand sits in edit and post as much as on set.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a64b36e59e34184ae1fb884', 'star-sports-chora-chori', 'Star Sports', 'Chora Chori', '2025-09-30', NULL, 'Atul Kattukaran', 'atul-kattukaran', NULL, 'TVC', NULL, 'Hindi', '["Media, broadcast & entertainment", "Sports"]', 'cause', 'A wordplay flip of the familiar chhora and chhori gender line, using parallel construction to place the women''s game beside the men''s and ask why the girls should count for less', '["rousing", "proud", "provocative", "celebratory"]', NULL, 'standard', '["sport"]', '["Star Sports: Chora Chori | ABBY Awards 2026 (Gold)", "Star Sports: Women''s Chora Chori | Kyoorius Creative Awards 2026 (Baby Blue Elephant)"]', 'Gold at the ABBY Awards 2026 for Best TV Sports Channel Program Promo, and a Baby Blue Elephant at the Kyoorius Creative Awards 2026 in Broadcast / Promos.', 'A useful reference for a broadcast sports programming promo built around an equality idea rather than a fixture listing. The script hangs on a piece of colloquial Hindi wordplay about boys and girls, flipping it so the women''s game is measured on the same terms as the men''s, and it is timed to a tentpole tournament season. Production shape is a promo cut for channel air: cricket action, athletes and crowd energy, shot for rhythm and voice rather than dialogue scenes. Tone is proud, rousing and lightly provocative, with a line that lands as a chant. Good comparable for award winning promo work on a national sporting moment.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e60', 'little-bangalore', 'First December Films', 'little BANGALORE', '2012-08-24', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=C-f99zVjaVw', 'short', 305, NULL, '["Social impact, nonprofit & cause-driven"]', 'other', 'self-initiated city portrait using tilt-shift miniature photography and timelapse, cut to an original score, framed as a written love letter to the city and its people', '["warm", "nostalgic", "celebratory", "observational", "affectionate"]', NULL, 'complex', '["multi_location", "music_led", "crowd"]', '[]', NULL, 'A useful reference for a self-initiated or brand-funded city tribute: a five minute non-dialogue portrait that stitches many public locations across one metro into a single emotional arc, held together by an original score and a short piece of written voice or text rather than a story with actors. The device is tilt-shift miniature photography and timelapse, so ordinary streets, markets, rooftops, traffic and crowds read as a toy world. Production shape is run and gun across dozens of city locations with permissions, rooftop access and long lock-off camera time. Tone is warm, nostalgic and affectionate, closer to a music promo than an advertisement.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e5e', 'nike-make-every-yard-count', 'Nike', 'Nike Make Every Yard Count', '2014-07-07', 'JWT Bangalore + Ogilvy Bangalore', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=RXxKnnZoe_8', 'brand film', 84, NULL, '["Sportswear & Athletic", "Sports"]', 'brand film', 'A single cricket delivery, from grip and run-up to release and the field scrambling, assembled stop-motion style from stills of 1,440 young cricketers so that no one person bowls the ball and the country does', '["rousing", "gritty", "youthful", "authentic"]', NULL, 'complex', '["sport", "crowd", "kids", "multi_location", "animation"]', '["Nike Cricket: Make Every Yard Count | Goafest National Awards 2014-15", "Nike Cricket: Make Every Yard Count | Adfest Asia Pacific 2014-15 (Lotus)", "Nike Cricket: Make Every Yard Count | Clio Awards 2014-15 (Clio)", "Nike Cricket: Make Every Yard Count | Spikes Asia 2014-15 (Silver)", "Nike Cricket: Make Every Yard Count | Spikes Asia 2014-15 (Gold)", "Nike Cricket: Make Every Yard Count | D&AD 2014-15 (Graphite Pencil)", "Nike Cricket: Make Every Yard Count | The One Show 2014-15 (Silver Pencil)", "Nike Cricket: Make Every Yard Count | The One Show 2014-15 (Gold Pencil)", "Nike Cricket: Make Every Yard Count | Cannes Lions 2014-15 (Lion)"]', 'Over 50 international awards, including a record 7 Cannes Lions, 3 One Show Gold Pencils (Film, Film Craft, Film Innovation), 4 One Show Silver Pencils, 6 D&AD Pencils including a Graphite Pencil, 5 Clios including India''s first Clio for Cinematography, 2 Gold and 5 Silver at Spikes Asia, 6 Adfest Lotus, 10 Goafest National Awards, and a place in Adweek''s World''s Best Commercials', 'Reach for this when a youth sports or participation brief needs the audience inside the film rather than watching it. The device is a single cricket delivery broken into keyframed positions and rebuilt from stills contributed by more than a thousand young players across the country, so the production method is the idea. Production shape is unusual: months of pre-production writing a capture brief simple enough for a teenager with a phone, crowd-sourced photography from many cities intercut with controlled professional frames, and an edit and sound design built from real field chants that carry the whole thing. Tone is raw, rousing and street-level.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e5c', 'nexa-maruti-suzuki-baleno-tvc', 'Maruti Suzuki NEXA', 'NEXA Maruti Suzuki Baleno TVC', '2015-10-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=DKrYz543eUY', 'TVC', 61, NULL, '["Automotive & Auto Marketplaces", "Retail"]', 'launch', 'Non-narrative mood film with a three-line voice-over, built entirely from projection lighting inside a showroom, cutting between a couple in evening dress and fragments of the car so light stands in for motion', '["premium", "cinematic", "atmospheric", "high-energy", "aspirational"]', NULL, 'standard', '["night", "vehicle"]', '[]', 'Case study states 634,000 views for the 37-second television cut and 38,000 views for the full film on the brand channel by September 2026.', 'A useful reference for a premium launch spot that opens pre-bookings before the product is on sale, and for selling a retail experience rather than a price. The device is a car film with no road: everything happens at night inside a single showroom, with slatted beams, bursts, sparks and geometric frames all thrown in camera by projection lighting rather than added in post. Small cast, a couple in evening dress, fragments of the vehicle shot like jewellery, monochrome throughout to separate a premium sub-brand from its mass parent. Sparse voice-over over a composed score. Tone is cool, formal and aspirational.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e5a', 'star-sports-womens-day', 'Star Sports', '#CheckOutMyGame: Women’s Day', '2015-11-10', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=nduhtCItin8', 'brand film', 65, NULL, '["Media, broadcast & entertainment"]', 'cause', 'Sportswomen address the camera and confront the male gaze, challenging viewers to judge their game rather than their looks', '["defiant", "purposeful", "empowering", "direct"]', NULL, 'standard', '["sport"]', '["Star Sports: Check Out My Game (Women''s Day) | PromaxBDA Asia 2015 (Silver)"]', 'Silver at PromaxBDA Asia 2015', 'A useful reference for a broadcaster or brand cause film built around International Women''s Day and women in sport. The device is direct address: female athletes look down the lens and turn the male gaze back on the viewer, so the writing lives in short confrontational lines rather than plot. Production shape is manageable, a set of athlete portraits and action moments across sporting environments, real sportswomen rather than actors, daylight and controlled arena or court setups, with wardrobe and kit continuity to manage. Tone is defiant and purposeful, sixty five seconds, cut tight to build to a single challenge.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e58', 'phive-river', 'Phive Rivers', 'Mancrafted', '2015-11-29', 'Hakuhodo Percept, New Delhi', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=ZuENImkF0Wg', 'brand film', 62, NULL, '["fashion", "leather goods", "accessories"]', 'brand film', 'craft-led product storytelling, following the making of leather goods as the hero of the film', '["cinematic", "crafted", "premium", "understated"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a craft-led fashion or accessories brand film where the making of the product carries the story rather than dialogue or a celebrity face. The script leans on close observation of hands, tools, material and texture, cut into a short cinematic sequence of roughly a minute for a leather goods label. Production shape is manageable: a workshop or atelier style setting, small cast of makers or models, controlled lighting for texture and detail work, and a macro-capable package. Tone is premium, tactile and understated, aimed at building brand character for a young fashion label.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e56', 'vivo-ipl-hotstar-digital-dildar-tvc', 'VIVO', 'Vivo IPL Hotstar Digital Dildar TVC', '2016-03-28', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=24Vxj6eSiBA', 'TVC', 100, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'other', NULL, '[]', NULL, 'standard', '["music_led", "sport"]', '[]', NULL, 'A useful reference for cricket-season digital campaigns built around a streaming platform and a handset sponsor, where the film has to work for tournament-scale viewing rather than a single product demo. Roughly a hundred seconds, so long enough to carry a set-up and pay-off rather than a single line. The music sits at the centre of the piece, with an original score by a well known film composer, which makes it a good comparison for scripts that want a track to drive pace and mood. Suited to briefs asking for tournament energy, fan behaviour and a title phrase that can be repeated across cutdowns.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e54', 'channel-v-ident', 'Channel V', 'Channel V Ident', '2016-08-16', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=_wG3ItX-GOs', 'other', 40, NULL, '["Media, broadcast & entertainment"]', 'brand film', 'broadcast design in motion, a short station identity built on graphic attitude rather than story', '["irreverent", "youthful", "high energy", "stylised"]', NULL, 'standard', '[]', '["Channel V: Promo | Promax 2017 (Gold)"]', 'Gold at Promax 2017', 'A useful reference for short form channel identity work: a forty second station ident for a youth music broadcaster, built as broadcast design in motion rather than a narrative spot. Worth pulling up when a brief asks for network branding, a title sequence, a channel refresh package or any burst of graphic led attitude that has to register the brand in seconds. The production shape is compact and design driven, leaning on art direction, motion and cut over dialogue or location scale. Tone is irreverent, young and stylised, matching the channel''s built in swagger. Award recognised in the broadcast promotion category.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e52', 'bbc-earth', 'BBC Earth', 'BBC Earth', '2017-03-10', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=oNEyDSht1vM', 'brand film', 71, NULL, '["Media, broadcast & entertainment"]', 'brand film', 'VFX-led natural history spectacle positioning a global factual channel for an Indian television audience', '["awe-inspiring", "cinematic", "grand"]', NULL, 'complex', '["vfx"]', '[]', NULL, 'A useful reference for a broadcast channel brand film where the promise of the network has to be dramatised rather than demonstrated. The script leans on VFX-built natural history spectacle, scale and wonder, cut to just over a minute for on-air use, so the production shape is closer to a post-heavy build than a location shoot: plate work, compositing, grade and a sound design that carries the emotion. Tone is awestruck and cinematic, aimed at an Indian television audience being introduced to a factual entertainment proposition. Reach for it when a channel launch or repositioning brief needs spectacle and craft over dialogue or talent.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e50', 'nexa-ciaz-tvc', 'Maruti Suzuki NEXA', 'NEXA Ciaz TVC', '2017-04-07', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=sMLxt94csEg', 'TVC', 61, NULL, '["Automotive & Auto Marketplaces"]', 'brand film', 'Mood-led product showcase built on clean lines, city light and a tone of quiet confidence rather than dialogue-driven story', '["premium", "understated", "confident", "aspirational"]', NULL, 'standard', '["vehicle"]', '[]', NULL, 'A useful reference for a premium sedan commercial that sells a car through mood and retail identity rather than plot. The script leans on the vehicle as hero, shot for clean lines and reflective surfaces, with urban light doing most of the storytelling and a calm, understated register instead of hard product claims. Production shape is a city-based car shoot with tracking and beauty passes, a small cast, and a single continuous look across locations, so it suits briefs that need controlled lighting, careful car detailing and a soundtrack-plus-voice finish. Handy for aspirational automotive work aimed at an upmarket buyer.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e4e', 'brezza-singles-film', 'Maruti Suzuki', 'Brezza Singles Film', '2017-04-07', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=tZuBG3SEETI', 'TVC', 21, NULL, '["Automotive & Auto Marketplaces"]', 'brand film', 'Short vignette built around a young, urban theme of independence and single living, with the compact SUV as the hero', '["young", "urban", "upbeat", "aspirational"]', NULL, 'standard', '["vehicle"]', '[]', NULL, 'A useful reference for a short form automotive television spot that sells a compact SUV to a young, urban, single audience rather than to families. The script leans on a lifestyle vignette about independence, letting the car function as a character in city life instead of relying on feature callouts, and it lands the idea inside roughly twenty seconds. Production shape is a vehicle led shoot with picture car handling, city locations and a small principal cast, so budget sits with car prep, tracking and clean urban dressing. Tone is contemporary, confident and light, suitable for national broadcast and digital rotation.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e4c', 'trends-music-video', 'Reliance Trends', 'Trends Music Video', '2018-06-21', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=VrWXbKPEW2Y', 'brand film', 66, NULL, '["Fashion", "Retail"]', 'brand film', 'music video format, track led cutting with performance and styling rather than dialogue', '["energetic", "youthful", "stylish", "upbeat"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'A useful reference for a fashion retail brand film built as a music video rather than a dialogue script. The cut is driven end to end by a track, with styling, movement and performance carrying the story, so the edit and choreography do the work a voice over would normally do. Production shape is a short form piece of roughly a minute with a young ensemble cast, multiple looks and wardrobe changes, and a styling and art led approach that needs a costume and grooming team on the floor. Tone is upbeat, youthful and aspirational, suited to seasonal apparel pushes and store led fashion campaigns.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e4a', 'bhima-jewellers', 'Bhima Jewellers', 'Bhima Jewellers', '2018-08-03', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=Gl72T_N_H94', 'TVC', 60, NULL, '["Gifting & occasions", "Fashion", "Jewellery"]', 'brand film', 'Bridal moment storytelling built around a young woman at the centre of a family occasion, with the jewellery framed as the emblem of her day', '["emotional", "celebratory", "warm", "aspirational"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for bridal and occasion led jewellery briefs where the product has to carry emotion rather than detail. The script leans on a single heroine at the centre of a family celebration, with the wedding ritual and the reactions around her doing the emotional work while the gold is treated as the emblem of the moment. Production shape is a one minute broadcast spot: dressed interiors with a festive family gathering, styled bridal costume and jewellery, careful close beauty and product coverage, and warm decorative lighting. Tone is heritage led, celebratory and aspirational, suited to national television and digital rotation.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e48', 'atul-kattukaran-2', 'Atul Kattukaran', 'Atul Kattukaran Showreel', '2018-10-25', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=cePadgR9H9M', 'other', 526, NULL, '["Media, broadcast & entertainment"]', 'other', 'long-form montage of excerpts cut from an existing commercial filmography', '["premium", "energetic", "cinematic"]', NULL, 'complex', '["multi_location", "music_led"]', '[]', NULL, 'A useful reference for a long-form directing reel built to introduce a body of work to clients and agencies. The device is a music-led montage of excerpts pulled from finished TVCs and brand films for large advertisers across sport, technology, fashion and beverages, so the production shape is an edit and grade job rather than a shoot, drawing on many locations, casts and day and night looks already in the can. Tone is premium and cinematic with pace held across nearly nine minutes. Good comparable when a client wants a compilation, sizzle or capability film assembled from existing footage.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e46', 'atul-kattukaran', 'Atul Kattukaran', 'Atul Kattukaran Showreel', '2018-10-25', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=z9upXIfJJwA', 'other', 243, NULL, '["Media, broadcast & entertainment", "Advertising"]', 'other', 'Montage showreel cut from commercial work across multiple brands', '["premium", "high energy", "cinematic"]', NULL, 'complex', '["multi_location", "music_led", "sport"]', '[]', NULL, 'A four minute directing showreel cut as a fast montage of commercial work spanning sportswear, sports broadcast, natural history, denim and sports nutrition brands. Useful as a reference when a client wants a credentials or capability reel that stitches many existing films into a single music led piece, or when the brief calls for a premium, cinematic treatment across many looks, locations and casts rather than one story. Shows how varied footage can be paced and graded into one coherent tone, and gives a sense of range across athletic, lifestyle and documentary style visual language.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e44', 'levi-s-performance-denim-2', 'Levis', 'Levi’s Performance Denim', '2019-03-14', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=bJQdfAQctoc', 'TVC', 56, NULL, '["Fashion", "Apparel"]', 'brand film', NULL, '[]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a short apparel brand spot built around a performance denim product line, cut at under a minute for television and digital rotation. It sits in a family of films made for the same campaign world, so it is a good comparable when a client asks for an alternate cut or a second execution that shares look, grade and edit rhythm with a lead film rather than starting fresh. Production shape is a standard fashion shoot with a director and cinematographer team, small crew scale and no specialist departments indicated in the available sources.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e42', 'flipkart-equals-day', 'Flipkart', 'Flipkart Equals Day', '2019-04-14', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=5OXQaxkWXro', 'digital film', 91, NULL, '["E-commerce"]', 'cause', 'purpose-led equality message built around an internal diversity and inclusion moment', '["sincere", "purpose-led", "warm"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a purpose-led cause film for a large consumer technology or e-commerce brand, where the ask is an equality and inclusion message rather than a product sell. Runs at around ninety seconds, longer than a broadcast spot and shaped for digital, so the script has room to build a point of view before landing the brand line. Production shape is moderate: real-feeling contemporary settings, an ensemble of everyday characters rather than a star face, daylight photography and dialogue or voice carrying the argument. Tone is sincere and warm without becoming preachy, with craft used in service of the cause.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e40', 'levi-s-performance-denim', 'Levis', 'Levi’s Performance Denim', '2019-04-18', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=isMchJY1Sw8', 'TVC', 56, NULL, '["Fashion", "Apparel"]', 'product demo', 'movement-led product demonstration, with fabric technology and stretch proven through choreographed physical action rather than dialogue', '["energetic", "dynamic", "aspirational", "contemporary"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a fashion or apparel product demonstration where a garment benefit has to be shown rather than explained. The script proves fabric stretch and durability through choreographed movement and physical action, so the storytelling load sits with casting, body performance, camera choreography and cutting rhythm rather than dialogue or voice-over. Production shape is a short television and digital spot, styled cast, controlled locations, lighting and grade built around the denim, and a track driving the pace. Tone is energetic, contemporary and aspirational. Good comparable when a client wants a technology or performance claim in a category that is usually sold on attitude alone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e3e', 'vaseline-a-journey-of-healing', 'Vaseline', 'Vaseline - A Journey of Healing', '2019-05-16', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=Rf8HxpRELwI', 'brand film', 94, NULL, '["FMCG", "Healthcare, pharma & wellness"]', 'cause', 'Documentary-style portraits of real, weathered hands and the lives attached to them, reframing skincare as healing and recovery rather than vanity', '["emotional", "sincere", "understated", "hopeful", "purpose-led"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for purpose-led skincare or wellness brand films that want to move away from beauty gloss and talk about healing instead. The script works through observational portraiture, close study of real, weathered hands and the everyday lives behind them, built as a quiet montage rather than a plotted story, with voice or music carrying the emotional line across roughly ninety seconds. Production shape is documentary-leaning and crew-light in feel, with several cinematographers covering real people in real settings, so casting for authenticity and location texture matters more than sets. Tone is sincere, restrained and dignified, with warmth earned rather than declared.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e3c', 'vivo-s1-tvc', 'VIVO', 'Vivo S1 TVC', '2019-09-03', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=IY1Exzg73Dg', 'TVC', 30, NULL, '["Consumer Technology", "Smartphones"]', 'launch', NULL, '["aspirational", "stylish", "youthful"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a smartphone launch spot cut to thirty seconds for television and digital, where the handset is the hero and the styling carries the idea. The shape is style-first product advertising aimed at a young urban audience, so expect controlled sets or curated locations, a small cast of good looking young talent, careful lighting on the device, and product beauty coverage sitting alongside lifestyle moments. Pull this when the brief calls for a launch window film that must feel premium and current without a heavy story, and when the tone needs to be aspirational, energetic and design led.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e3a', 'muscleblaze', 'Muscle Blaze', 'MuscleBlaze', '2019-09-17', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=adzo0WggzZ0', 'anthem', 64, NULL, '["Healthcare, pharma & wellness", "Sportswear & Athletic"]', 'brand film', 'Anthem manifesto framing sports nutrition as national self belief, carried by documentary style training footage', '["gritty", "aspirational", "motivational", "high energy"]', NULL, 'standard', '["sport"]', '[]', NULL, 'A useful reference for a category anthem that argues a bigger idea than the product, in this case sports nutrition positioned as national self belief. The script is built as a manifesto rather than a story: sweat, discipline and iron shown in documentary style, handheld and textured, cut to a rising voice track so the emotional volume climbs to a single claim at the end. Production shape is gym and training environments with athletic casting, real bodies over models, practical light and minimal set build. Good comparison for wellness, fitness or athletic wear briefs wanting grit and pride rather than polish, in a tight sixty second cut.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e38', 'bose-noise-cancelling-headphones', 'Bose', 'Bose Noise Cancelling Headphones', '2019-10-03', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=bYIRrbKaieE', 'TVC', 30, NULL, '["Consumer Technology", "Consumer Electronics"]', 'product demo', 'Product benefit dramatised as silence being a superpower, with sound design carrying the selling as much as the visuals', '["premium", "atmospheric", "understated"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'A useful reference for a thirty second hero product film for a premium consumer technology launch, built to run on television and digital. The script sells a single functional benefit, noise cancellation, by dramatising silence itself, so the sound mix carries as much of the argument as the picture and the edit is cut to audio rather than dialogue. Production shape is a controlled product film with small cast and tightly art directed environments rather than a location travelogue, with careful attention to product beauty coverage. Tone is premium, calm and understated, aimed at an international brand standard set by a Singapore agency brief.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e36', 'hrx-ft-hrithik-roshan', 'HRX', 'HRX ft. Hrithik Roshan', '2019-11-05', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=9sHXJsWrZME', 'TVC', 63, NULL, '["Sportswear & Athletic", "Fashion"]', 'brand film', 'celebrity founder fronting the brand as athlete protagonist', '["aspirational", "high energy", "stylised"]', 'Hrithik Roshan', 'complex', '["sport"]', '[]', NULL, 'A useful reference for a star-led athleisure or fitness brand film where the founder is also the face, carrying a short sixty second brand statement rather than a product demo. The script leans on a single charismatic performer shot with strong craft, training and movement energy, and a tone that is aspirational, stylised and high in attitude. Production shape assumes celebrity talent handling, tight shoot days built around limited star availability, controlled sets or gym style spaces, wardrobe and styling support, and a cut driven by music and rhythm. Good comparable when a client wants the idea to stay bigger than the famous face.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e34', 'google-be-unstoppable-tvc', 'Google', 'Google - Be Unstoppable TVC', '2019-11-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=qVSjX7zms20', 'anthem', 60, NULL, '["Consumer Technology"]', 'brand film', 'manifesto voice-over framing search as the quiet engine behind everyday ambition', '["aspirational", "uplifting", "warm"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a sixty second brand anthem for a technology platform, where the product is invisible and the film has to carry a manifesto idea instead of a demo. The script leans on a spoken through line about ambition and persistence, with everyday moments of people finding a way through rather than around, so the shape is vignette led and needs casting breadth and location variety rather than one long scene. Tone is aspirational and warm without sentimentality, cut for national television and digital rotation, and paced so the voice and music do much of the emotional work.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e32', 'dettol-minipack-director-s-cut', 'Dettol', 'Dettol Minipack (Director’s Cut)', '2020-01-27', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=xzxhABfO4tQ', 'TVC', 20, NULL, '["FMCG", "hygiene and personal care"]', 'other', NULL, '["warm", "earnest"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a short twenty second hygiene commercial built around affordability, where a small pack size and a low price point carry the message to a mass audience without the film feeling cheap. Relevant when a client wants an everyday product proposition told with care rather than a hard sell, and when a director''s cut is being kept alongside the aired version for craft. The sources describe only the intent and the credits, so treat it as a tonal and length reference for warm, earnest, value led personal care work rather than a guide to scale or cast.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e30', 'jsw-paints', 'JSW Paints', 'JSW Paints', '2020-04-22', 'TBWA Mumbai', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=6VVVvxjGcEQ', 'brand film', 75, NULL, '["Home & Living", "paints", "decor"]', 'brand film', 'voice-over led montage of homes, assembled from footage captured remotely by multiple contributors and cinematographers rather than a single unit shoot', '["warm", "uplifting", "reflective", "optimistic"]', NULL, 'complex', '["multi_location", "music_led"]', '[]', NULL, 'A useful reference for a brand film in the paints, decor and home category that needs to feel colour led and emotionally warm without a conventional single unit shoot. The script is carried by a female voice-over and an original music track over a montage of real homes and interiors, stitched together from footage captured by several cinematographers and a long list of contributors in different locations. Good comparable for remote or distributed production, lockdown style self shot gathering, heavy editorial assembly and post led craft, and for any seventy five second film where the storytelling load sits with narration, music and colour rather than performance.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e2e', 'nestl-nangrow', 'Nestle', 'Nestle Nangrow', '2020-05-07', 'McCann Delhi', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=EMnb3PlM3m0', 'TVC', 58, NULL, '["FMCG", "food and beverage", "child nutrition"]', 'brand film', 'montage of multiple mother and child pairs carried by a voice-over and a sung track, with CG and illustrated graphic support', '["warm", "reassuring", "upbeat", "family"]', NULL, 'complex', '["kids", "vfx", "music_led", "animation"]', '[]', NULL, 'A useful reference for a children''s nutrition brief that needs warmth and reassurance rather than a hard sell. The script runs as a short montage cut across many mother and child pairings, roughly ten sets of talent, which means heavy child casting, chaperones, short usable shooting windows per child and a director comfortable getting natural behaviour from toddlers. Sung track and voice-over carry the through line, so music and edit rhythm do much of the storytelling work. A CG and illustration layer sits over the live action for nutrition and growth cues. Shape is daytime, clean domestic or studio setups, moderate build, tone gentle and optimistic.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e2c', 'india-gate', 'India Gate', 'India Gate', '2020-05-13', 'Lowe Lintas, Delhi', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=yGdsrgBgsGs', 'TVC', 59, NULL, '["FMCG", "food and beverage", "packaged rice"]', 'brand film', 'montage of many households captured across separate homes, intercut with tabletop food craft and carried by a single voice-over line', '["warm", "emotional", "celebratory", "homely"]', NULL, 'complex', '["food", "multi_location"]', '[]', NULL, 'A useful reference for a national staple food brand spot that needs appetite appeal and emotional warmth in under a minute. The script stitches together a very large ensemble of ordinary families filmed in their own homes with close tabletop and food craft passes of cooked rice, held together by a voice-over and an original music bed. Production shape is unusual: multiple cinematographers, contributed footage from several cities, dozens of credited cast members and a heavy post and edit load rather than one big set. Look here for distributed, many-household shooting married to controlled food photography, in a warm daytime domestic register.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e2a', 'bookmyshow', 'Book My Show', 'BookMyShow', '2020-10-27', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=uHyNDsBYrmU', 'digital film', 30, NULL, '["E-commerce", "Media, broadcast & entertainment"]', 'brand film', NULL, '[]', NULL, 'standard', '[]', '[]', NULL, 'A short thirty second social-first brand film for a ticketing platform covering cinema and live events, useful as a reference for entertainment and e-commerce brand work that has to land quickly in a feed. Production shape is a styled ensemble piece with six credited on-screen performers, a full art department, stylist and hair and make-up team, shot with a compact single unit crew and a line producer, which suggests controlled set-built or dressed locations rather than sprawling multi-location coverage. Post includes online, external grade and a dedicated music director and sound studio, so the cut leans on music and finish to carry the energy.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e28', 'pepe-jeans', 'Pepe Jeans', 'Pepe Jeans', '2020-10-27', 'White Board', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=Gx7oGzGdVwM', 'brand film', 44, NULL, '["Fashion"]', 'brand film', 'choreography led fashion vignette built around styled talent moving to an original music track', '["energetic", "stylish", "youthful", "confident"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'A useful reference for a short fashion brand film that sells attitude rather than product features. The script is choreography led, carrying a small ensemble of styled models and a bboy dancer through movement cut to an original music track, with a stylist, hair and make up and an art director shaping a controlled look. Production shape is compact but craft heavy: a set or single dressed location, gaffer and intelligent lighting for a moody, designed feel, focus pulling for close movement, and a full grade and sound finish. Good comparison for denim, streetwear or youth apparel briefs needing a fast, confident, forty second cut.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e26', 'fastrack-reflex-3-0', 'Fastrack', 'Fastrack Reflex 3.0', '2021-03-23', 'Lowe Lintas (Bangalore)', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=WCUIBTvFBCg', 'TVC', 30, NULL, '["Consumer Technology", "Fashion", "Wearables"]', 'launch', 'Product-led launch film built around the smart band and a styled young cast, carried by an original track rather than dialogue', '["youthful", "energetic", "stylish", "upbeat"]', NULL, 'standard', '["music_led", "animation"]', '[]', NULL, 'A useful reference for a thirty second wearable or smart device launch cut for both television and digital. The shape is a product hero film aimed at a young urban audience: a cast found through casting and styling rather than a name face, tight camera work on the band and on faces, on screen animation to sell the interface and features, and an original sung track with a named singer doing the emotional lifting instead of dialogue. Crew list points to a controlled shoot with art direction, styling and hair and make up departments, graded and finished in post. Tone is fast, fashionable and upbeat.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e24', 'myntra-ipl-film', 'Myntra', 'Myntra IPL Film', '2021-04-24', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=8yU7RUIRFY0', 'TVC', 40, NULL, '["E-commerce", "Fashion", "Retail"]', 'other', 'Seasonal cricket tie-in built around a celebrity fashion expert idea, one film within a linked campaign set', '["upbeat", "aspirational", "stylish"]', NULL, 'complex', '["sport"]', '[]', NULL, 'A useful reference for short form seasonal retail work timed to the cricket calendar, where a fashion platform needs a forty second spot that sits inside a larger connected campaign rather than standing alone. The production shape is talent led and styling heavy, with a dedicated stylist, hair and make up and an art department, plus a second unit style line production set up in Delhi alongside the Mumbai core team. Worth pulling out when a brief asks for polished, well graded lifestyle imagery, a scored music bed and a bright, aspirational tone that can be cut into multiple matching executions.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e22', 'unacademy-believe', 'Unacademy', 'Unacademy Believe', '2021-06-17', 'Lowe Lintas, Bangalore', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=WX5af34u4oo', 'anthem', 146, NULL, '["Education & EdTech"]', 'brand film', 'Music led anthem cut to a licensed rock track, with choreographed ensemble movement and CG enhanced set pieces staging self belief as the brand argument', '["rousing", "emotive", "high energy", "aspirational"]', NULL, 'complex', '["vfx", "crowd", "music_led"]', '[]', NULL, 'A useful reference for a category defining edtech anthem that argues ambition and self belief rather than demonstrating a product. The script is carried by a licensed international rock track, so performance, choreography and cutting to beat do the storytelling instead of dialogue. Production shape is large: a lead performer plus heavily styled extras, a choreographer and assistants, second unit direction and photography, built art sets, and two CG houses feeding an online and grade pipeline. Good comparison for briefs that want scale, ensemble movement and a two minute plus running time at full emotional volume, with a polished, cinematic, slightly heroic tone.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e20', 'myntra-x-hrithik-roshan', 'Myntra', 'Myntra X Hrithik Roshan', '2021-09-11', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=Pg5RvHnf7t0', 'TVC', 35, NULL, '["E-commerce", "Fashion"]', 'brand film', 'celebrity-led brand positioning, with a star fronting the fashion expert idea in a choreographed, styled performance', '["stylish", "aspirational", "upbeat", "confident"]', 'Hrithik Roshan', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a short celebrity-fronted fashion or e-commerce spot built around a single male star as the face of a category expertise idea. The script leans on styling, wardrobe changes and choreographed movement rather than dialogue-heavy storytelling, so it shows how to handle a star entourage of costume stylist, hair and make-up alongside a choreographer, art department and a second unit within a tight thirty-five second cut. Shot on built sets with strong art direction and a music-driven edit, it is also a template for one film inside a wider celebrity series sharing a common look, tone and campaign line.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e1e', 'myntra-x-kiara-advani-ethnic-wear', 'Myntra', 'Myntra X Kiara Advani (Ethnic Wear)', '2021-09-11', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=2z5chGFqT_Y', 'TVC', 35, NULL, '["E-commerce", "Fashion", "Retail"]', 'brand film', 'Celebrity-fronted category showcase, with a lead actor presenting ethnic wear looks through styled, choreographed vignettes as part of a wider series', '["aspirational", "stylish", "upbeat", "glossy"]', 'Kiara Advani', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for short, celebrity-fronted fashion category films built to sit inside a larger series with a single campaign idea. The script leans on a female lead presenting ethnic looks through quick styled vignettes cut to a track, with a choreographer shaping movement and an art department building clean, colour-led sets. Production shape is a controlled studio or set build with a full talent entourage of stylist, hair and make-up, a body double for wardrobe changes, steadicam and second unit coverage, and a grade and online finish. Tone is glossy, aspirational and upbeat, aimed at a thirty-five second cutdown.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb99073afa6d12df9e1c', 'myntra-x-kiara-advani-western-wear', 'Myntra', 'Myntra X Kiara Advani (Western Wear)', '2021-09-11', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=0aWsGr9q9LM', 'TVC', 35, NULL, '["E-commerce", "Fashion"]', 'other', 'Celebrity-led fashion category showcase, styled looks presented as a choreographed, music-driven sequence', '["aspirational", "stylish", "upbeat", "glossy"]', 'Kiara Advani', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a short, high-gloss fashion category film built around a female film star, where the brief is to make a marketplace feel like a style authority in a category push rather than tell a story. The script leans on styled looks, wardrobe changes and choreographed movement cut to a music track instead of dialogue, so the production shape covers a set-built or art-directed studio environment, a full talent entourage of costume, hair and make-up, a choreographer, a body double, steadicam and second unit camera coverage, and a finish with online, grade and sound. It also works as a template for one film in a connected multi-film campaign set, with an aspirational, confident, contemporary tone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b760d', 'myntra-x-dulquer-salmaan', 'Myntra', 'Myntra X Dulquer Salmaan', '2021-09-11', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=oybTVyXCnhw', 'TVC', 35, NULL, '["E-commerce", "Fashion"]', 'brand film', 'celebrity endorser fronting the brand as a fashion expert, one spot within a connected series built on a single campaign idea', '["stylish", "upbeat", "aspirational"]', 'Dulquer Salmaan', 'complex', '["music_led", "multi_location"]', '[]', NULL, 'A useful reference for short, celebrity-fronted fashion e-commerce spots where a star acts as the brand''s style authority and the same idea is extended across a connected set of films. The build is a thirty five second cut carrying a full star entourage of costume, hair and makeup, a body double, choreography and a purpose built art department set, shot with a second unit and a separate Hyderabad crew alongside the Mumbai team, so it shows the shape of a multi city, talent led schedule. Tone is glossy, upbeat and music driven, with grading and online finishing pitched at high fashion polish.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b760b', 'myntra-x-vijay-deverakonda', 'Myntra', 'Myntra X Vijay Deverakonda', '2021-09-11', 'Brave New World', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=vORv_J3sutg', 'TVC', 35, NULL, '["E-commerce", "Fashion"]', 'brand film', 'Celebrity-fronted fashion endorsement built around a single star performance, with choreography suggesting a music and movement led treatment', '["stylish", "upbeat", "aspirational"]', 'Vijay Deverakonda', 'complex', '["music_led", "multi_location"]', '[]', NULL, 'A useful reference for a short, star-led fashion or e-commerce spot where a single celebrity carries the whole idea in about thirty five seconds. The script leans on styling, wardrobe changes and a choreographed, music driven performance rather than dialogue heavy storytelling, so it needs a proper art department, a costume, hair and make-up entourage travelling with the talent, and a body double for coverage. Shot with a unit split across Mumbai and Hyderabad, with steadicam and a second unit camera team, plus online, grade and sound finishing. Tone is glossy, confident and aspirational, and it sits inside a connected set of films built as a series under one campaign idea.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b7609', 'facebook-roar-together-director-s-cut', 'Facebook', 'Facebook Roar Together (Director’s Cut)', '2021-09-13', 'Dentsu Mcgarrybowen', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=_cdjkxBnDS8', 'brand film', 528, 'Malayalam', '["Consumer Technology", "Social Media"]', 'brand film', 'Long form ensemble story built around a Kerala folk performance troupe, carried by original music, local dialogue and a large community cast', '["warm", "celebratory", "rooted", "emotive"]', NULL, 'complex', '["crowd", "music_led"]', '[]', NULL, 'Useful reference for a long form branded story that runs close to nine minutes and behaves like a short film rather than a spot. The script leans on a regional folk performance troupe, local dialogue, original composition with live percussion and vocals, and an ensemble of largely non star actors cast in Kerala, with community groups such as painters and performers appearing as themselves. Production shape is a travelling unit with a local line producing team, built sets and art department, styling and hair and make up units, plus a second unit camera. Tone is warm, celebratory and rooted in place.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b7607', 'pepperfry-ten-year-rap', 'Pepperfry', 'Pepperfry Ten Year Rap', '2021-12-30', 'Publicis Groupe & L&K Saatchi', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=2D0zLQmdTZI', 'brand film', 59, NULL, '["E-commerce", "Home & Living", "Furniture retail"]', 'brand film', 'Anniversary story told as an original rap track, with a choreographed ensemble performing to camera across styled furniture sets', '["celebratory", "upbeat", "playful", "music-led"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'A useful reference for a brand milestone or anniversary brief that needs a decade of business story compressed into under a minute without a talking-head montage. The device is an original rap track, with lyrics carrying the narrative and a choreographed ensemble of roughly a dozen performers moving through dressed interior sets. Production shape is a built art-directed environment with a full art team, styling, hair and make-up, choreographer and assistants, steadicam coverage and a music production plus sound mix in post. Tone is upbeat, celebratory and lightly cheeky, aimed at a home and living retail audience rather than a hard product demo.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b7605', 'unacademy-teachers-day', 'Unacademy', 'Unacademy Teachers Day', '2022-01-07', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=jX2a3nTSHVo', 'digital film', 95, 'Hindi and English', '["Education & EdTech"]', 'cause', 'Found footage tribute cut entirely from educators'' own recorded classes, re-edited as a music video with glitch effects, split screens and bold captions telling the teachers to relax', '["playful", "affectionate", "energetic", "celebratory", "irreverent"]', NULL, 'contained', '["music_led"]', '[]', '2.3 million views on the Unacademy India channel', 'A useful reference for a calendar moment tribute built without a shoot. The whole piece is assembled from existing screen recordings of online classes, re-cut to a fast track so real teachers become unwitting performers, with glitch transitions, colour bars, mirrored frames and hard bold Hindi and English typography carrying the message. Production shape is edit and post only, no unit, no cast call, no locations, which makes it the model for briefs with a tight turnaround, spread out contributors or user generated and platform footage as the source. Tone is affectionate and funny rather than sentimental, praising people by showing their effort instead of describing it.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b7603', 'pepperfry-ten-year-rap-director-s-cut', 'Pepperfry', 'Pepperfry Ten Year Rap (Director’s Cut)', '2022-01-07', 'L&K Saatchi & Saatchi', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=9DoAID1WiwQ', 'brand film', 83, NULL, '["E-commerce", "Home & Living"]', 'brand film', 'original rap track carrying the brand''s ten year story, performed music video style by a choreographed ensemble across furnished set vignettes', '["upbeat", "celebratory", "playful", "stylised"]', NULL, 'complex', '["music_led", "crowd"]', '[]', NULL, 'A useful reference for a milestone or anniversary brand film that replaces dialogue with an original rap track and choreography. The script rides a bespoke music bed with two singers, so music production, playback and a choreographer with assistant choreographers sit at the centre of the schedule alongside the camera unit. Production shape is a large ensemble of thirteen credited performers styled and made up in blocks, art directed home and living set vignettes built by a dedicated art team, and steadicam coverage to keep the performance moving. Tone is upbeat, celebratory and playful, with a stylised, design led finish carried through grade, online and sound.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b7601', 'iqoo-9-series-120w-flashcharge', 'iQOO', 'iQOO 9 Series 120w Flashcharge', '2022-03-04', 'Dentsu Webchutney (Delhi)', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=4uC8WvzRfLY', 'TVC', 15, NULL, '["Consumer Technology"]', 'launch', 'speed as the single proposition, a fast fifteen second product-led piece built around the charging feature', '["high energy", "slick", "youthful"]', NULL, 'complex', '["vfx", "stunts"]', '[]', NULL, 'A useful reference for a short, sharply cut smartphone launch spot where one feature, in this case charging speed, carries the entire idea. The script turns a spec into visual momentum, so the film leans on CG and online work from two animation houses, a stunt director and practical SFX, plus steadicam and probe lens coverage on built sets with an art and set decoration team. Cast is small but styled and cast for a young urban look, with featured casting handled separately in Delhi. Also relevant when planning a connected set of launch films sharing one campaign device, and for slick, high energy tech tone at fifteen seconds.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75ff', 'iqoo-9-series-ultimate-gaming', 'iQOO', 'iQOO 9 Series Ultimate Gaming', '2022-03-04', 'Dentsu Webchutney (Delhi)', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=fgUp7bWaFOM', 'TVC', 15, NULL, '["Consumer Technology"]', 'launch', 'Gaming-led product feature spot, one instalment of a three-part device launch series built on a single campaign idea', '["high energy", "stylised"]', NULL, 'complex', '["vfx", "stunts"]', '[]', NULL, 'A useful reference for a short, punchy handset launch spot aimed at gamers, made as one part of a connected three-film series under a single campaign idea. The shape is a built set with a dedicated art and set decoration team, a styled young ensemble cast found through casting rather than a famous face, and camera work using steadicam and probe lenses to keep the energy high in fifteen seconds. Two CG houses plus practical SFX and a stunt director sit behind the action, so budget the post and safety departments accordingly. Tone is slick, fast and youth facing, with strong sound and grade finishing.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75fd', 'iqoo-9-series-gimbal-camera', 'iQOO', 'iQOO 9 Series Gimbal Camera', '2022-03-11', 'Dentsu Webchutney (Delhi)', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=n47UBTudagA', 'TVC', 15, NULL, '["Consumer Technology", "Smartphones"]', 'launch', 'single-feature product spot built around the gimbal camera, one of three connected launch films sharing a campaign idea', '["slick", "energetic", "tech-forward"]', NULL, 'complex', '["vfx", "stunts"]', '[]', NULL, 'A useful reference for a short-format smartphone launch spot that dramatises one camera feature and sits inside a trilogy of matching films, so the look, grade and music have to carry across the set. The production shape is agency-heavy with a Delhi client team, a four-hander cast found through casting and featured casting, a built and dressed set with styling and make-up departments, and a camera package including steadicam, probe and DSLR units. Specialist support covers a stunt director, practical effects and two CG houses feeding online and colour finishing. Tone is slick, fast and tech-forward within fifteen seconds.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75fb', 'youtube-ka-maza-ab-short-mein-shorts', 'YouTube', 'YouTube ka maza, ab short mein #Shorts', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=R9NjCp7E6Aw', 'digital film', 30, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'vertical short-form cut of a longer launch film, built around the promise of the same entertainment in a shorter format', '["youthful", "upbeat", "playful"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a platform or app launch that needs a vertical, thirty second cut sized for feeds and in-app placements, sitting inside a larger multi-language rollout. The script leans on a simple promise, the same entertainment delivered in a shorter form, and is pitched at a young Hindi speaking audience. Production shape is a compact day shoot cut for portrait framing, with the edit and post doing much of the work to keep energy high in a short runtime. Tone is youthful, playful and fast, with the language version and the vertical crop planned from the start rather than retrofitted.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75f9', 'youtube-ka-maza-ab-short-mein-5', 'YouTube', 'YouTube ka maza, ab short mein', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=rhKnm-f0lKs', 'TVC', 15, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', NULL, '["youthful", "energetic"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for short form platform launch work aimed at young urban audiences, where a single fifteen second Hindi cut has to land a simple proposition fast and sit inside a larger multi film, multi language rollout. Producers can look at it when a brief calls for a batch of tightly scripted films shot together across a shared production window, with a small cast, quick set ups and a snappy cutting rhythm rather than one long hero narrative. Tone is bright, contemporary and youth facing, built for feed and pre roll placement where the first two seconds carry the whole idea.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75f7', 'youtube-ka-maza-ab-short-mein-4', 'YouTube', 'YouTube ka maza, ab short mein', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=PTGX4356Np8', 'digital film', 15, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', NULL, '[]', NULL, 'standard', '[]', '[]', NULL, 'Useful as a reference for short form platform launch work: a fifteen second Hindi cut built as one of several films rolled out together across languages to introduce a new product feature to a young audience. The shape is a quick, single idea spot sized for feeds and vertical placements rather than a long narrative, so it suits briefs that need a bank of tight, repeatable executions shot economically off a shared setup. Also a reference for handling a multi film launch slate under one director with a lean producing team and fast post turnaround across the set.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75f5', 'youtube-ka-maza-ab-short-mein-3', 'YouTube', 'YouTube ka maza, ab short mein', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=K-D3CvPihV0', 'digital film', 15, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', NULL, '["youthful", "upbeat"]', NULL, 'standard', '[]', '[]', NULL, 'Useful as a reference for very short vertical launch work aimed at a young Hindi speaking audience, where a fifteen second cut has to land a single idea and a tagline with no room for setup. It sits inside a multi film, multi language rollout, so it is a good example of how one creative platform is executed as repeatable short episodes with a shared look, pace and sign off. Production shape is lean and crew light, built for volume across several films rather than one large shoot. Tone is fast, playful and contemporary.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75f3', 'youtube-ka-maza-ab-short-mein-2', 'YouTube', 'YouTube ka maza, ab short mein', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=2ofsniPE49E', 'digital film', 15, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'Short-form music-led vignette built around a popular track, cut to vertical short video behaviour', '["youthful", "energetic", "playful"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'A useful reference for a fifteen second launch film selling a short video product to a young Hindi speaking audience, made as one cut in a multilingual versioning run where the same idea is reshot or re-edited across languages. The device is music led rather than dialogue led, hanging on a recognisable film track and quick vertical style cutting, so the edit and sound design carry the story more than performance. Production shape is light and fast, a small cast of young performers, simple contemporary settings and daylight, with the main demand being tight scheduling across several films in one block. Tone is upbeat, playful and trend aware.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75f1', 'youtube-ka-maza-ab-short-mein', 'YouTube', 'YouTube ka maza, ab short mein', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=SR4aCfGkXys', 'digital film', 15, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'Short-form platform launch built around a popular music track, with the vertical Shorts format itself as the storytelling frame', '["energetic", "youthful", "playful", "music-led"]', NULL, 'standard', '["music_led"]', '[]', NULL, 'Useful reference for a fifteen second platform or app launch aimed at young audiences, cut to a recognisable music track and built for vertical, short form consumption. The device is speed: a familiar song hook carrying a burst of performance and quick cuts that sell the format rather than a feature list. Production shape is compact, one Hindi execution within a multi language launch set, small cast, tight shoot, heavy reliance on edit, sound sync and choreography timing in post. Tone is upbeat, youthful and playful. Good comparable when a brief needs one idea rolled out across several languages.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75ef', 'youtube-oda-maja-ippo-short-la-2', 'YouTube', 'YouTube oda maja, ippo short la', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=7j8mQq0rtBY', 'digital film', 15, 'Tamil', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'Short-form platform launch cut built around a punchy vernacular tagline promising that the fun now comes in short form', '["energetic", "youthful", "playful", "fast-paced"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for fifteen second platform launch work made in regional language cuts, where the same idea is rolled out across several films and tongues to introduce a short-form video product to young viewers. The script leans on a colloquial Tamil line and a mass, high-energy delivery rather than a long narrative, so the value sits in casting, wardrobe and cutting pace inside a compact shoot. Production shape looks light: small cast, limited setups, day work, no specialist departments flagged. Good comparison point for briefs asking for snackable, vertical-friendly launch films with a confident, streetwise tone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75ed', 'youtube-oda-maja-ippo-short-la', 'YouTube', 'YouTube oda maja, ippo short la', '2022-03-31', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=TQLY4GpO4RE', 'TVC', 15, 'Tamil', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', NULL, '["youthful", "upbeat"]', NULL, 'standard', '[]', '[]', NULL, 'Useful as a reference for a fifteen second platform launch spot built for a young, mobile first audience, made as the Tamil cut within a multi language, multi film rollout. Worth pulling up when a brief needs one short idea that has to hold up across several language versions with matching energy, casting and cutting rhythm, and when the schedule involves shooting or adapting a family of films together rather than a single hero execution. Production shape is modest in scale with a compact crew, and the tone is light, playful and fast paced, aimed at a social feed rather than a long form viewing.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75eb', 'youtube-shorts-x-badshah-4', 'YouTube', 'YouTube Shorts X Badshah', '2022-03-31', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=THJWfZA38HI', 'digital film', 10, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'Short teaser built around a celebrity talent fronting a coming soon platform announcement', '["youthful", "energetic", "playful"]', 'Badshah', 'complex', '[]', '[]', NULL, 'A useful reference for a very short platform teaser that leans entirely on a celebrity face to announce something coming soon. Ten seconds, one talent, built as part of a multi-film, multi-language launch push aimed at a young audience, so the shape is a set of quick modular cuts rather than a single narrative. Production is designed rather than location led, with a built set and controlled art direction, a small cast and a strong colour grade doing much of the personality work. Tone is youthful, punchy and pop culture facing, with the talent''s own persona carrying the message.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75e9', 'youtube-shorts-x-badshah-3', 'YouTube', 'YouTube Shorts X Badshah', '2022-04-12', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=yl_cgevMLMU', 'series', 6, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity-fronted teaser built around a musician, one of several very short films cut for a platform push', '["energetic", "youthful", "playful"]', 'Badshah', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a platform or app launch push that leans on a music celebrity rather than a story, cut as a six second teaser and released as part of a multi film series aimed at young audiences. The script shape is star to camera, high energy, designed to be recognised in a scroll and to trail a bigger campaign. Production shape is compact and studio led with designed sets, a controlled lighting package and colour finishing, but budget sits in talent handling, a tight shoot window with an artist, and shooting several teasers in the same block. Tone is punchy, confident and youth facing.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75e7', 'youtube-shorts-x-badshah-2', 'YouTube', 'YouTube Shorts X Badshah', '2022-04-12', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=fUfyIDdTfsM', 'digital film', 16, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity direct address inviting viewers to participate', '["energetic", "youthful", "playful"]', 'Badshah', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a short, punchy platform launch spot built entirely around a music celebrity speaking straight to camera and inviting young viewers to join in and create. The shape is compact: a designed studio or single set build, controlled lighting, one hero talent, and a sixteen second cut that has to land a call to action fast. Production design and colour do the heavy lifting to give a stylised, high energy look that reads well on mobile and in vertical formats. Tone is confident, playful and youth facing, and it sits inside a multi film, multi language rollout so the set-up is designed for repeat shooting across variants.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75e5', 'youtube-shorts-x-badshah', 'YouTube', 'YouTube Shorts X Badshah', '2022-04-12', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=fTPGNcMfbqo', 'digital film', 6, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity-fronted teaser for a platform launch', '["youthful", "energetic", "punchy"]', 'Badshah', 'complex', '[]', '[]', NULL, 'Useful reference for a very short, celebrity-fronted teaser cut as part of a wider multi-film, multi-language platform launch aimed at young creators. The device is simple: one famous face carrying a six second hook that sets up longer films in the same campaign, so the whole idea has to land in a single beat of performance and one clear visual. Production shape is studio-led with a designed set, controlled lighting and a small unit built around a star talent day. Tone is loud, youthful and playful, closer to music and creator culture than conventional advertising, and it suits briefs needing many teaser cutdowns from one build.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75e3', 'howtojugnu-with-badshah-on-youtube-shorts', 'YouTube', '#HowToJugnu with Badshah on YouTube Shorts', '2022-04-12', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=ROK7gnnOG-k', 'digital film', 57, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity-led how-to: a musician teaches viewers a song hook as a short-form format demo, direct to camera', '["playful", "energetic", "youthful", "music-led"]', 'Badshah', 'complex', '["music_led", "crowd"]', '[]', NULL, 'A useful reference for short-form platform launch work that leans on a music celebrity to teach the audience a format. The script is a direct to camera how-to built around a song hook, so the shape is a controlled studio or single set build with designed production values, tight vertical friendly framing and performance driven cutting rather than location work. Talent handling and a compressed shoot window around a musician''s availability are the main production considerations, along with art direction that reads instantly on a phone. Tone is playful, youthful and music-led, and it sits inside a wider multi-film, multi-language launch push.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75e1', 'jugnuchallenge-on', 'YouTube', '#JugnuChallenge on fire', '2022-04-12', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=hDIbW1Bsg1o', 'digital film', 27, 'Hindi', '["Consumer Technology", "Media, broadcast & entertainment"]', 'other', 'Fast-cut montage of creators across India performing the same dance hook, intercut with the artist, building the sense of a trend catching on', '["energetic", "celebratory", "youthful", "music-led"]', 'Badshah', 'complex', '["music_led", "crowd", "multi_location"]', '[]', NULL, 'A useful reference for short-form platform work that needs to feel like a trend rather than an advert: a momentum piece cut to a music hook, built from many creators performing the same dance step in different rooms, streets and cities, intercut with the recording artist. The production shape is a mix of controlled artist coverage and a high volume of user-style clips, so scheduling leans on one focused celebrity block plus a wide net of creator content. Tone is loud, young and celebratory, with cutting driven entirely by the track. Good for challenge launches, creator-led campaigns and very short cutdowns.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75df', 'ather-director-s-cut', 'Ather Energy', 'Ather (Director’s Cut)', '2022-07-26', NULL, 'Shiv Parameswaran', 'shiv-parameswaran', 'https://www.youtube.com/watch?v=DTeF4Y3Bsws', 'brand film', 15, NULL, '["Automotive & Auto Marketplaces"]', 'brand film', NULL, '["crafted"]', NULL, 'standard', '["vehicle"]', '[]', NULL, 'Useful as a reference for a short electric two wheeler brand film handled as a craft piece, the director''s own edit kept alongside the delivered cut. Production shape is a full unit on location with a line production partner, location managers and a production designer, a cast led by a principal with secondary cast supplied and separately styled, and a dedicated casting director. Post is craft heavy for a fifteen second running time, with offline, grade, online and an originally directed music and sound pass. Reach for it when a client wants a premium, design led product and lifestyle film that reads modern and urban rather than dialogue driven.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75dd', 'acid-attack-beauty-tips-by-reshma-how-to-get-perfect-red-lip', 'Make Love Not Scars', '#ACID ATTACK Beauty Tips by Reshma: How to get perfect red lips', '2015-09-01', 'Ogilvy & Mather', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=o7hTynP5p6Y', 'digital film', 67, 'Hindi with English subtitles', '["Social impact, nonprofit & cause-driven"]', 'cause', 'A beauty vlogger tutorial played completely straight, with an acid attack survivor teaching a red lip step by step until one written line turns the tutorial into a petition, format intact and picture unchanged', '["sincere", "understated", "restrained", "direct address", "quietly devastating"]', NULL, 'contained', '[]', '["Beauty Tips by Reshma: CNBC-TV18 Awards 2017 (Award)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Golden Elephant)", "Beauty Tips by Reshma: Cannes Lions 2017 (Silver Lion)", "Beauty Tips by Reshma: India Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold) #2", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold)", "Beauty Tips by Reshma: Asia Pacific Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Bronze) #2", "Beauty Tips by Reshma: AMES 2016 (Bronze)", "Beauty Tips by Reshma: AMES 2016 (Silver) #5", "Beauty Tips by Reshma: AMES 2016 (Silver) #4", "Beauty Tips by Reshma: AMES 2016 (Silver) #3", "Beauty Tips by Reshma: AMES 2016 (Silver) #2", "Beauty Tips by Reshma: AMES 2016 (Gold) #2", "Beauty Tips by Reshma: AMES 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Gold)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #8", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #7", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #6", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #5", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #4", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Brass & Wood Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Black Elephant)", "Beauty Tips by Reshma: Spikes Asia 2016 (Bronze)", "Beauty Tips by Reshma: Spikes Asia 2016 (Silver)", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold) #2", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold)", "Beauty Tips by Reshma: The One Show 2016 (Merit) #2", "Beauty Tips by Reshma: The One Show 2016 (Merit)", "Beauty Tips by Reshma: The One Show 2016 (Gold Pencil)", "Beauty Tips by Reshma: D&AD Impact 2016 (White Pencil)", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil) #2", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil)", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #9", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #8", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #7", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #6", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #5", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #4", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #3", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #2", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist)", "Beauty Tips by Reshma: Cannes Lions 2016 (Gold Lion)", "Beauty Tips by Reshma: Cannes Lions 2016 (Glass Lion)"]', 'Cannes Lions 2016 Gold Lion in Film and Glass Lion for Change, plus a 2017 Silver Lion; D&AD Impact 2016 White Pencil and two D&AD Wood Pencils; The One Show 2016 Gold Pencil and two Merits; Kyoorius 2016 Black Elephant for Best of Show with eight Blue Elephants; Spikes Asia 2016 two Gold, one Silver, one Bronze; two Gold and a Silver at India Effie 2016 and a Silver at Asia Pacific Effie; listed among Adweek''s World''s Best Commercials of 2016; fifty honours recorded in total. The petition passed 2,25,000 signatures within a fortnight against a 25,000 target and went beyond 3,00,000.', 'Useful reference for a cause or advocacy brief that has to reach people who would scroll past the subject if they saw it coming. It borrows an existing internet format, the beauty tutorial, and plays it sincerely rather than as parody, with numbered tip cards, product inserts and direct address to lens, then turns the whole thing on a single written line that lands as a petition ask with one link as the call to action. Production shape is deliberately small: one dressed vanity set, fairy lights, day interior, a single non professional performer carrying every frame, plus cosmetic inserts. Restrained, plain lit, no score telling you how to feel, Hindi performance with English subtitles.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75db', 'acid-attack-beauty-tips-by-reshma-how-to-apply-eyeliner', 'Make Love Not Scars', '#ACID ATTACK Beauty Tips by Reshma: How to apply eyeliner', '2015-09-01', 'Ogilvy & Mather', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=FzIs2TvHjWc', 'digital film', 64, 'English', '["Social impact, nonprofit & cause-driven"]', 'cause', 'Beauty vlog format subverted: an acid attack survivor presents a chirpy how-to makeup tutorial to camera, using the tutorial''s own language to deliver an advocacy message about the easy sale of acid', '["disarming", "direct", "unsettling", "warm", "purposeful"]', NULL, 'contained', '[]', '["Beauty Tips by Reshma: CNBC-TV18 Awards 2017 (Award)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Golden Elephant)", "Beauty Tips by Reshma: Cannes Lions 2017 (Silver Lion)", "Beauty Tips by Reshma: India Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold) #2", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold)", "Beauty Tips by Reshma: Asia Pacific Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Bronze) #2", "Beauty Tips by Reshma: AMES 2016 (Bronze)", "Beauty Tips by Reshma: AMES 2016 (Silver) #5", "Beauty Tips by Reshma: AMES 2016 (Silver) #4", "Beauty Tips by Reshma: AMES 2016 (Silver) #3", "Beauty Tips by Reshma: AMES 2016 (Silver) #2", "Beauty Tips by Reshma: AMES 2016 (Gold) #2", "Beauty Tips by Reshma: AMES 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Gold)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #8", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #7", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #6", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #5", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #4", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Brass & Wood Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Black Elephant)", "Beauty Tips by Reshma: Spikes Asia 2016 (Bronze)", "Beauty Tips by Reshma: Spikes Asia 2016 (Silver)", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold) #2", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold)", "Beauty Tips by Reshma: The One Show 2016 (Merit) #2", "Beauty Tips by Reshma: The One Show 2016 (Merit)", "Beauty Tips by Reshma: The One Show 2016 (Gold Pencil)", "Beauty Tips by Reshma: D&AD Impact 2016 (White Pencil)", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil) #2", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil)", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #9", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #8", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #7", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #6", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #5", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #4", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #3", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #2", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist)", "Beauty Tips by Reshma: Cannes Lions 2016 (Gold Lion)", "Beauty Tips by Reshma: Cannes Lions 2016 (Glass Lion)"]', 'CMS-listed verified awards include Cannes Lions 2016 Glass Lion and Gold Lion, Cannes Lions 2017 Silver Lion, D&AD Impact 2016 White Pencil, The One Show 2016 Gold Pencil, Spikes Asia 2016 Gold, Kyoorius Black Elephant and Golden Elephant, and Effie Gold at India Effie Awards 2016; CMS also states the campaign gathered over 225,000 petition signatures.', 'A useful reference for cause and advocacy briefs that hijack a familiar content format rather than dramatise a victim story. The script borrows the beauty tutorial: a single presenter talking straight to camera in a bright home setting, walking viewers through winged eyeliner before the turn lands the real message about buying acid over the counter. Production shape is deliberately small, one interior, daylight, one real protagonist rather than an actor, minimal crew and no specialist departments, which keeps the vlog texture credible. Tone is chirpy and disarming on the surface with a hard advocacy payload underneath, built to travel as social video and to seed press coverage.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75d9', 'acid-attack-beauty-tips-by-reshma-how-to-get-rid-of-dark-spo', 'Make Love Not Scars', '#ACID ATTACK Beauty Tips by Reshma: How to get rid of dark spots naturally', '2015-09-01', 'Ogilvy & Mather', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=dQVy3kqv084', 'digital film', 65, NULL, '["Social impact, nonprofit & cause-driven"]', 'cause', 'subverted beauty vlog: a direct to camera tutorial format that switches from cosmetic advice to a petition against open acid sales', '["direct", "unsettling", "earnest", "activist"]', NULL, 'contained', '[]', '["Beauty Tips by Reshma: CNBC-TV18 Awards 2017 (Award)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2017 (Golden Elephant)", "Beauty Tips by Reshma: Cannes Lions 2017 (Silver Lion)", "Beauty Tips by Reshma: India Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold) #2", "Beauty Tips by Reshma: India Effie Awards 2016 (Gold)", "Beauty Tips by Reshma: Asia Pacific Effie Awards 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Bronze) #2", "Beauty Tips by Reshma: AMES 2016 (Bronze)", "Beauty Tips by Reshma: AMES 2016 (Silver) #5", "Beauty Tips by Reshma: AMES 2016 (Silver) #4", "Beauty Tips by Reshma: AMES 2016 (Silver) #3", "Beauty Tips by Reshma: AMES 2016 (Silver) #2", "Beauty Tips by Reshma: AMES 2016 (Gold) #2", "Beauty Tips by Reshma: AMES 2016 (Silver)", "Beauty Tips by Reshma: AMES 2016 (Gold)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #8", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #7", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #6", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #5", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #4", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #3", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant) #2", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Blue Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Brass & Wood Elephant)", "Beauty Tips by Reshma: Kyoorius Creative Awards 2016 (Black Elephant)", "Beauty Tips by Reshma: Spikes Asia 2016 (Bronze)", "Beauty Tips by Reshma: Spikes Asia 2016 (Silver)", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold) #2", "Beauty Tips by Reshma: Spikes Asia 2016 (Gold)", "Beauty Tips by Reshma: The One Show 2016 (Merit) #2", "Beauty Tips by Reshma: The One Show 2016 (Merit)", "Beauty Tips by Reshma: The One Show 2016 (Gold Pencil)", "Beauty Tips by Reshma: D&AD Impact 2016 (White Pencil)", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil) #2", "Beauty Tips by Reshma: D&AD 2016 (Wood Pencil)", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #9", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #8", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #7", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #6", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #5", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #4", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #3", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #2", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist)", "Beauty Tips by Reshma: Cannes Lions 2016 (Gold Lion)", "Beauty Tips by Reshma: Cannes Lions 2016 (Glass Lion)"]', 'Cannes Lions 2016 Glass Lion and Gold Lion, plus Cannes Lions 2017 Silver Lion, D&AD Impact 2016 White Pencil, The One Show 2016 Gold Pencil, Spikes Asia 2016 Gold, Kyoorius Black Elephant and Golden Elephant, India Effie Awards 2016 Gold, and CNBC-TV18 Awards 2017.', 'A useful reference for cause and advocacy briefs that hijack a familiar content format to deliver a hard message. The script borrows the language of a how to beauty tutorial, with a young woman speaking straight to camera in a warm domestic setting, before the advice turns into a call to stop open acid sales and a petition ask. Production shape is deliberately small: single interior location, one performer, natural light styling, day shoot, no specialist departments, cut short at just over a minute for social. Tone is calm and friendly on the surface with a deeply uncomfortable turn, and the casting of a real survivor carries the whole idea.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75d7', 'get-ready-to-manikemove-ft-nora-fatehi-yohani-jubin-nautiyal', 'YouTube', 'Get ready to #ManikeMove ft. Nora Fatehi, Yohani, Jubin Nautiyal', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=2yIz_iU9QmU', 'digital film', 20, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity-led dance challenge built around a hook step, cut to a popular track to invite user participation', '["energetic", "playful", "music-led", "aspirational"]', 'Nora Fatehi, Yohani, Jubin Nautiyal', 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for short form platform launch work that needs a music and dance challenge to travel as user generated content. The script rides a hook step choreographed for easy imitation, performed by a film star and two singers, cut tight to twenty seconds. Production shape is a studio or built set with a production designer, a movement director and assistant choreographers, an entourage managed cast of three names, plus a CG house and online for graphic polish. Tone is high energy, colourful and playful, aimed at getting viewers to copy the move rather than watch a story.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75d5', 'join-the-manikemove-dance-challenge-ft-nora-fatehi-yohani-ju', 'YouTube', 'Join the #ManikeMove dance challenge ft. Nora Fatehi, Yohani, Jubin Nautiyal', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=OU61Vk2NC_I', 'digital film', 20, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'other', 'Celebrity-led call to action built around a hook step, with artists performing the dance move and inviting viewers to recreate it on Shorts', '["energetic", "playful", "music-led", "aspirational"]', 'Nora Fatehi, Yohani, Jubin Nautiyal', 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for short-form social calls to action that ask an audience to join a dance or participation challenge on a platform. The script leans on a music track and a single repeatable hook step, performed by multiple well known artists and playback singers, so the production shape involves choreography and a movement director, assistant choreographers, a built and designed set, styling and entourage handling for several talents, and a compact twenty second cut. Post includes CG support, online and grade. Tone is high energy, colourful and celebratory, made to be imitated rather than simply watched.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75d3', 'learn-how-to-create-a-short-ft-nora-fatehi-manikemove', 'YouTube', 'Learn how to create a Short ft. Nora Fatehi #ManikeMove', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=SwJfu1qmolo', 'digital film', 36, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'product demo', 'celebrity-led how-to walkthrough, a step by step tutorial on making a Short built around a dance hook step and challenge', '["energetic", "playful", "upbeat", "aspirational"]', 'Nora Fatehi', 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for a short form platform brief that has to teach a feature while entertaining, in this case a celebrity walking the viewer through making a vertical Short as part of a music and dance challenge. The script leans on a choreographed hook step, direct address to camera and clean on screen demonstration of the app steps, so it needs a movement director, assistant choreographers, a designed set and a CG plus online pass for interface and graphic layers. Production shape is a single controlled studio build, a star talent day with entourage handling, and a bright, high energy pop tone cut tight to under forty seconds.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75d1', 'learn-how-to-do-the-manikemove-ft-nora-fatehi', 'YouTube', 'Learn how to do the #ManikeMove ft. Nora Fatehi', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=cRG0FR0Edqw', 'digital film', 47, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'celebrity-led dance tutorial breaking a hook step into learnable moves', '["energetic", "playful", "aspirational"]', 'Nora Fatehi', 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for short form, creator style platform work built around a music trend, where a celebrity dancer demonstrates a hook step and breaks it down for viewers to copy at home. The shape is compact but specialist: a designed studio set, a movement director and choreography team, a named hook step creator, plus CG and online finishing on top of a live action shoot. Cast is small and the running time is under a minute, cut for vertical Shorts consumption. Tone is bright, high energy and participatory, with clean lighting, bold production design and a direct invitation to join in.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75cf', 'learn-how-to-do-the-manikemove-ft-yohani-jubin-nautiyal', 'YouTube', 'Learn how to do the #ManikeMove ft. Yohani and Jubin Nautiyal', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=lD1lUhXdans', 'digital film', 47, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'other', 'celebrity-led dance tutorial delivered to camera, breaking a song''s hook step down for viewers to copy', '["upbeat", "playful", "energetic"]', 'Yohani, Jubin Nautiyal', 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for short form platform work built around a music trend, where two well known singers front a quick tutorial teaching a dance hook step straight to camera. The script shape is instructional rather than narrative, so it leans on choreography, a designed studio set and graphic overlays to carry the beats within under a minute. Production involves a movement director and assistant choreographers, a dedicated hook step credit, a built set, celebrity entourage handling and a CG and online post pass. Tone is upbeat, playful and youth facing, pitched at creators being invited to join in.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75cd', 'stars-are-doing-the-manikemove', 'YouTube', 'Stars are doing the #ManikeMove', '2022-10-25', 'Dentsu Webchutney, Bangalore', 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=8jtcg42UPng', 'digital film', 20, NULL, '["Consumer Technology", "Media, broadcast & entertainment"]', 'other', 'celebrity round-up montage built around a single dance hook step set to a trending track', '["energetic", "playful", "music-led", "youthful"]', NULL, 'complex', '["music_led", "vfx"]', '[]', NULL, 'A useful reference for short-form platform challenge work: a twenty second celebrity round-up cut around one repeatable dance hook, designed to seed a Shorts trend. The production shape is choreography-first, with a movement director, a named hook step choreographer and a team of assistant choreographers rehearsing multiple famous faces, plus built sets from a production designer, an entourage manager on the schedule and a CG house handling graphic and clean-up work in post. Look here for briefs that need many high-profile cast members shot quickly against designed backdrops, tight sync to a music track, and a bright, playful, trend-chasing tone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75cb', 'google-pixel-x-twinkle-khanna', 'Google Pixel', 'Google Pixel x Twinkle Khanna', '2022-11-24', 'Talented', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=0ZKNlWxz92s', 'TVC', 57, NULL, '["Consumer Technology"]', 'product demo', 'celebrity-fronted device film built around the star addressing the product', '["polished", "aspirational", "warm"]', 'Twinkle Khanna', 'complex', '[]', '[]', NULL, 'A useful reference for a short celebrity-led consumer technology device film cut for both television and digital. The script leans on a single well known face fronting the product, so the shape is talent-first: a controlled set with production design, styling, hair and make up and a full entourage schedule, a tight shoot window around star availability, and coverage that has to hold both the performer and clean product beats. Post is finish-heavy with online, grading, CG touch up and an original music track. Good comparison for brand teams planning a polished, warm, contemporary product spot where casting and turnaround drive the budget.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fcb0b9eb2ac28337b75c9', 'google-pixel-x-vicky-sunny-kaushal', 'Google Pixel', 'Google Pixel x Vicky and Sunny Kaushal', '2022-11-24', 'Talented', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=B2zKy5chMnI', 'TVC', 67, NULL, '["Consumer Technology"]', 'product demo', 'sibling comedy between two brothers used to demonstrate the phone camera', '["comedic", "warm", "playful"]', 'Vicky Kaushal, Sunny Kaushal', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a star-led smartphone product film that has to sell a camera feature without turning into a spec list. Two celebrity brothers play off each other, so the writing leans on sibling rivalry and banter as the demo device, with the feature landing inside the joke rather than in a voice-over. Production shape is a compact star shoot: designed sets, a stylist and separate hair and make-up units for each lead, a choreographer for movement beats, original music and a grade plus light CG finish. Tone is warm, quick and comic, cut tight for a minute-long TV and digital edit.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea91', 'reebok-ft-taapsee-sky', 'Reebok', 'Reebok ft. Taapsee and SKY', '2023-05-06', 'Lowe Lintas Bangalore', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=jFR0MRtaKM4', 'TVC', 45, NULL, '["Sportswear & Athletic", "Fashion"]', 'brand film', NULL, '["energetic", "aspirational"]', 'Taapsee Pannu, Suryakumar Yadav', 'complex', '["vfx", "sport", "music_led"]', '[]', NULL, 'A useful reference for a short, star-fronted sportswear brand spot built around two celebrity faces, one from film and one from cricket, where the craft has to carry the idea rather than lean on the names. Production shape is a full crew build with steadicam and dolly work, a designed set or controlled studio environment, a talent entourage with styling, hair and make-up to manage, and a post pipeline running CG, online and grade across multiple vendors plus an original music composition. Tone is energetic, athletic and aspirational, cut tight to a forty five second broadcast length.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea8f', 'reebok-ft-taapsee-sky-director-s-cut', 'Reebok', 'Reebok ft. Taapsee and SKY (Director’s Cut)', '2023-05-28', 'Lowe Lintas Bangalore', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=sBLjLhW4U_0', 'brand film', 56, NULL, '["Sportswear & Athletic", "Fashion"]', 'brand film', 'celebrity-led athlete portraiture, presented as the director''s own alternate cut of the campaign film', '["aspirational", "energetic", "stylised"]', 'Taapsee Pannu, Suryakumar Yadav', 'complex', '["vfx", "sport", "music_led"]', '[]', NULL, 'A useful reference for a sportswear or fashion brand film built around two high profile talents, an actor and an international cricketer, shot as a crafted athlete portrait rather than a product demo. The production shape is talent heavy: full celebrity entourage management, styling, hair and make up, vanity requirements and scheduling around two separate names, supported by a designed set built by a production design team, steadicam and dolly work, and an intelligent lighting rig. Post is substantial, with two CG studios, online and a separate grade, plus an original music composition. Tone is aspirational, energetic and stylised, and the cut runs under a minute.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea8d', 'licious-infinity', 'Licious', 'Licious Infinity', '2023-08-17', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=thhkLhOgyvo', 'TVC', 45, NULL, '["Quick Commerce", "FMCG", "Food Delivery"]', 'launch', 'Musical, choreographed spot built around a sung jingle, intercut with tabletop food craft and product beauty shots to sell a membership proposition', '["upbeat", "playful", "appetising", "energetic"]', NULL, 'standard', '["food", "music_led", "vfx"]', '[]', NULL, 'A useful reference for a membership or subscription proposition sold as a short, high energy musical rather than a talking head explainer. The script runs on a sung jingle with an original composition, playback singers and a choreographer working a small ensemble of three actors, cut against appetite led tabletop work with a dedicated food stylist and product specialist. Production shape is set built and studio controlled, with a designed environment, motion control camera passes and CG and online finishing for the product and benefit beats. Tone is bright, playful and appetising, aimed at national television and digital rotation in a tight forty five second cut.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea8b', 'muscleblaze-the-call', 'Muscle Blaze', 'MuscleBlaze - The Call', '2023-08-18', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=heWfGiGMJm8', 'anthem', 131, 'Hindi, English', '["Healthcare, pharma & wellness", "Sportswear & Athletic", "Nutrition & supplements"]', 'brand film', 'An inner voice narrates as a character while three interwoven training stories play out with no dialogue, props like a newspaper, a countdown on a wall and a missed-workouts board carrying the backstory', '["gritty", "emotive", "inspirational", "restrained"]', NULL, 'complex', '["multi_location", "night", "sport", "music_led", "animals"]', '[]', 'Case study states 10.1 million views for the Hindi film and 2.9 million for the English film on the brand channel by September 2026', 'A useful reference for a two-minute brand anthem that has to state what a fitness or supplement brand stands for at full emotional volume without falling into generic sweat montage. The device is a first-person inner voice used as a character, carrying three interwoven stories told with no dialogue, where a newspaper cutting, a countdown in marker pen and a whiteboard of missed workouts do the exposition. Production shape is multi-location: gyms, outdoor bars on a floodlit field at dawn, a staircase at night, a hall dressed with flags, plus a full lighting unit, gimbal work, real-body casting rather than models, a black-and-white overture and a grade arc from dark to bright. Score-led, delivered in two languages with separate native voice performances. Tone is gritty, tender and quietly triumphant.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea89', 'thums-up-toofan-director-s-cut', 'Thums Up', 'Thums Up Toofan (Director’s Cut)', '2024-04-03', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=GLnmLqYw-I0', 'TVC', 26, 'Hindi', '["Beverages", "FMCG"]', 'brand film', 'voice-over led cut set to an original music track', '["high energy", "bold", "cinematic"]', NULL, 'complex', '["vfx", "multi_location"]', '[]', NULL, 'A useful reference for a short, high impact cola brand spot cut in a punchy twenty six second form, built around a single male lead and carried by a strong voice-over and an original music score rather than dialogue. Production shape is a two city shoot with separate camera and assistant director units in Pune and Mumbai, jib and dolly work, a designed set look with dedicated production design, styling and hair and makeup, a product specialist for the pack and bottle beauty, plus CG, online and grade in post. Tone is bold, energetic and cinematic, suited to mass market beverage or FMCG briefs wanting craft led swagger.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea87', 'performax-x-bumrah-unstoppable-spirit-director-s-cut', 'Performax', 'Performax x Bumrah : Unstoppable Spirit (Director’s Cut)', '2024-04-07', 'Leo Burnett', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=WFTmUhGnrC0', 'anthem', 91, NULL, '["Sportswear & Athletic"]', 'brand film', 'celebrity athlete anthem fronted by a cricketer, built as a montage of training and endurance imagery cut to an original score', '["aspirational", "cinematic", "gritty", "heroic"]', 'Jasprit Bumrah', 'complex', '["vfx", "sport", "water", "multi_location", "music_led"]', '[]', NULL, 'A useful reference for a sportswear or performance brand anthem built around a signed athlete, where the script needs scale rather than dialogue. The production shape is a three unit shoot across Mumbai, Vajreshwari and Pune, with a full camera package including drone, FPV drone and an underwater operator, plus grip support, production design, styling and a casting team for supporting talent. Post carries CG, online and a dedicated grade, and an original music composition drives the cut. Look here when the brief calls for a heroic, cinematic training montage with celebrity handling, multiple terrains and water work, and a craft led director''s cut sensibility.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea85', 'igp-3', 'IGP', 'Amazing Gifts, Samay Par', '2024-10-28', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=mDpKGtaDyOM', 'series', 20, 'Hindi', '["Gifting & occasions", "E-commerce"]', 'festive', 'Retro Doordarshan-era pastiche, staging a festive gifting saga in the visual language of old state television as one chapter of a multi-film series', '["nostalgic", "witty", "warm"]', NULL, 'complex', '["period", "vfx"]', '[]', 'CMS states the series was inducted into the IMPACT Ads 2024 Hall of Fame.', 'A useful reference for a short festive e-commerce spot that sells delivery speed through period pastiche rather than product demo, dressing a gifting story in the look and rhythm of old state television. Twenty seconds, one of three linked films, so it shows how a single art direction and casting language can be repeated across a series. Production shape leans on a production designer, costume stylist and casting director for era-accurate ensemble faces, controlled interior sets, plus grade and CG support to age the image. Tone is nostalgic and gently comic, family friendly, with original music carrying the period feel.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea83', 'swiggy-xl', 'Swiggy', 'Swiggy XL', '2024-10-28', NULL, 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=K78sOK1ythc', 'digital film', 30, NULL, '["Quick Commerce", "QSR & Food Service", "Food Delivery"]', 'other', 'comic scenario built on comic timing, fronted by a single actor', '["comic", "light-hearted", "social-first"]', 'Aasif Ali', 'complex', '["vfx", "food"]', '[]', NULL, 'Useful as a reference for a short, social-first food delivery spot that leans entirely on comic timing and a single recognisable actor carrying the joke. Production shape is a crew-heavy but tightly scoped shoot: a casting director led lead, art department and costume styling building a designed everyday set, a second unit camera team for extra coverage, and a CG and online vendor handling clean-up or a light visual gag. Food appeal and product framing matter within a thirty second cut. Tone is playful and punchline driven, edited fast for feeds rather than television storytelling.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea81', 'igp-2', 'IGP', 'Amazing Gifts, Samay Par', '2024-10-28', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=1iKsveGnISs', 'TVC', 20, 'Hindi', '["Gifting & occasions", "E-commerce"]', 'festive', 'Period comic conceit, a birthday staged in the Stone Age, played in a retro Doordarshan style to land the same gifts on time promise across eras', '["comic", "quirky", "retro", "warm"]', NULL, 'complex', '["vfx", "period"]', '[]', 'CMS copy states the series was inducted into the IMPACT Ads 2024 Hall of Fame.', 'A useful reference for short festive gifting or delivery promise spots that repeat one comic device across a series of films. The script drops a modern gifting occasion into a distant era, so the whole gag rests on production design, costume, prosthetic leaning hair and make up and a deliberately retro television grade rather than dialogue. Built as a twenty second cut with a small ensemble cast from a casting director, a controlled set build, CG support for period set extension and clean up, and a bespoke music bed. Good comparison when a brief needs deadpan period comedy, tight running time and a repeatable format that can extend to further occasions.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea7f', 'knorr-x-netflix-x-squid-game-2', 'Knorr x Netflix', 'Dare-to-Slurp', '2024-12-13', 'Talented', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=mv3JrA3mDus', 'digital film', 90, NULL, '["FMCG", "Media, broadcast & entertainment", "Food & beverage"]', 'launch', 'Co-branded pop culture crossover, borrowing the world and visual codes of a streaming title to frame a dare style noodle challenge', '["playful", "high energy", "dramatic", "pop culture pastiche"]', 'Gulshan Grover', 'complex', '["food", "stunts", "music_led"]', '[]', NULL, 'A useful reference for a co-branded product film built on a streaming IP crossover, where a snack or instant food range is dropped into a recognisable show world and turned into a dare style challenge. The shape is a built set piece with a production designer, styled costumes, a choreographer and an action director, a well known screen face with his own styling and make up team, plus a food stylist and a custom pack maker for hero product shots. Ninety seconds, jib and steadicam coverage, original music and a graded, cinematic look. Tone is playful and heightened, leaning on menace as a joke rather than real threat.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea7d', 'fiama-5', 'Fiama', 'Fiama', '2024-12-24', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=0-4DcWqt780', 'TVC', 15, 'Hindi and English', '["FMCG", "personal care"]', 'product demo', 'A single claim made physical: the star lifted from a floor of bottles into a paper-cut world where a drifting feather stands in for skin friendly pH, ending on a claim badge and pack card', '["playful", "feel-good", "graphic", "sensorial"]', 'Sara Ali Khan', 'complex', '["vfx", "animation"]', '[]', 'Case study states the Hindi version passed 11 million views and the English version 1.5 million by September 2026, with the sibling moisturiser film at 14.9 million in Hindi.', 'A useful reference for a claim-led fifteen second television spot that has to sit inside a family of films sharing one world, one star and one line. The script turns an abstract product truth into a single physical image, a feather on skin, so the science becomes something an audience can feel. Production shape is a controlled studio shoot: a white cyclorama floor dressed with dozens of bottles, a celebrity shot clean so she can be composited into built paper-cut environments, then heavy CG and animation, a colour grade that keeps skin warm inside fully saturated worlds, and one music track cut across the set. Good for mixed media, colour coded, cheerful personal care work delivered in two languages.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea7b', 'fiama-4', 'Fiama', 'Fiama', '2024-12-24', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=qxC4n1GW6hY', 'TVC', 15, NULL, '["FMCG", "personal care"]', 'product demo', 'Short product-benefit spot built around a single moisturisation claim, made as one episode in a connected multi-film series sharing a single product world', '["clean", "bright", "product-led"]', NULL, 'complex', '["vfx", "animation"]', '[]', NULL, 'A useful reference for a short fifteen second personal care benefit spot that has to land one claim, in this case moisturisation, inside a tightly art directed product world. Worth pulling up when a client wants a set of episodic films shot together under one campaign idea, since the crew shape here covers a designed set build, a full line production team and a location manager, plus a CG and animation pass and an online artist for product and texture work. Tone is clean, bright and beauty led, with music and sound design carrying the pace rather than dialogue. Good shorthand for planning a multi film shoot block with post heavy finishing.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea79', 'fiama-3', 'Fiama', 'Fiama', '2024-12-24', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=yHL3vhvL8Zw', 'TVC', 15, NULL, '["FMCG", "personal care"]', 'product demo', 'single-proposition 15 second spot built as one part of a connected five-film set under a common campaign idea', '[]', NULL, 'complex', '["vfx", "animation"]', '[]', NULL, 'Useful reference for a short personal-care product proposition spot cut to fifteen seconds and designed to sit inside a connected set of films sharing one campaign idea, so the look, grade and sound have to carry across the whole batch. Production shape is a designed set build with a location manager and art department, a full line producing team, and a CG and animation pass plus online for product and finish work. Good comparison when a brief asks for several short films shot together on a single schedule, where economy comes from repeating the build and cast while each film lands its own single benefit message.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea77', 'fiama-2', 'Fiama', 'Fiama', '2024-12-24', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=ORKmrwedfvw', 'TVC', 15, NULL, '["FMCG", "personal care"]', 'product demo', NULL, '["clean", "stylised"]', NULL, 'complex', '["vfx", "animation"]', '[]', NULL, 'A useful reference for short form personal care advertising built as a connected set rather than a one off, where a single crafted world is designed to be reshot and recut across five films and multiple durations. The shape is a fifteen second spot with a product led idea around refilling, supported by a built set from a dedicated art department, a strong grade and CG and animation for product beauty and transitions. Point to this when a brief needs a repeatable TVC template, tight cutdowns, controlled studio style lighting and a polished, clean tone that keeps the pack and its benefit at the centre.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea75', 'fiama', 'Fiama', 'Fiama', '2024-12-24', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=9iXICJI0trQ', 'TVC', 15, NULL, '["FMCG", "personal care"]', 'product demo', 'Product benefit led short format built around a fragrance claim, made as one film in a connected set under a single campaign idea', '["sensorial", "premium", "upbeat"]', NULL, 'standard', '["vfx"]', '[]', NULL, 'A useful reference for a short fifteen second television spot for a personal care brand where the whole idea rests on a single sensory benefit, in this case fragrance, and the product has to be hero without a long story. The production shape is a controlled set build with a production designer and a location team, shot by a cinematographer for a glossy skin and lather look, then finished with CG and animation, online and grade to lift the fragrance idea beyond what camera alone can show. Tone is sensorial, premium and upbeat, and the film is designed to sit inside a family of matching cutdowns.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea73', 'wonderla-2', 'Wonderla', 'Wonderla', '2024-12-24', 'Talented', 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=7SkukInFLsQ', 'TVC', 45, NULL, '["Travel", "Media, broadcast & entertainment"]', 'festive', 'A mythological figure, the ten headed demon king of the festival, is cast as a delighted park guest, and each ride blows one head off in a burst of coloured smoke until the effigy burn at the end leaves him fully mind blown, turning the brand device into the plot and carrying a ticket offer', '["comic", "celebratory", "spectacular", "warm", "irreverent"]', NULL, 'complex', '["vfx", "kids", "crowd", "night", "water", "food"]', '[]', NULL, 'A useful reference for a festive brief that hijacks the festival''s own mythology rather than decorating with it, and that carries a hard ticket offer inside a story. The script turns a brand device into a plot: a costumed mythological guest loses one head per ride. Production shape is a live amusement park across day and night, real rides with camera mounts on a water plunge and a spinner, a practical ten headed headdress and shoulder build that survives water and rotation, a long feast table, a night drum procession with dancers, fireworks and an effigy burn, plus post added coloured smoke bursts. Tone is broad comic performance, bright and celebratory, played straight without irony.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea71', 'igp', 'IGP', 'Amazing Gifts, Samay Par', '2024-12-24', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=Ip7DsIs6XJo', 'TVC', 61, NULL, '["Gifting & occasions", "E-commerce"]', 'festive', 'Retro Doordarshan-styled pastiche, one of nine films that leap across eras from the Ice Age to 3000AD, each landing the promise that the gift arrives on time', '["nostalgic", "witty", "retro", "warm"]', NULL, 'complex', '["vfx", "period", "multi_location"]', '["IGP: Amazing Gifts, Samay Par | IMPACT Ads 2024 (Hall of Fame)"]', 'Inducted into the IMPACT Ads 2024 Hall of Fame.', 'A useful reference for a festive gifting or e-commerce delivery promise built as a period pastiche. The script hops between eras and mimics the look and grammar of old state broadcaster advertising, so the craft load sits in production design, costume, casting of character faces and CG set extension rather than in dialogue. Shot as part of a multi film campaign, so it also works as a template for a repeatable format where one comic promise is replayed across different worlds. Tone is affectionate, tongue in cheek and nostalgic, with a clean single line payoff at the end.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea6f', 'oppo-find-x8-series-ft-milind-soman', 'OPPO', 'Find Your Bigger Picture', '2024-12-26', 'Talented', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=QwMUATz0kl0', 'TVC', 60, NULL, '["Consumer Technology"]', 'launch', 'celebrity-led device film built around the phone''s camera and the idea of seeing a bigger picture', '["aspirational", "cinematic", "premium"]', 'Milind Soman', 'complex', '["multi_location"]', '[]', NULL, 'A useful reference for a smartphone launch spot that leans on a well known celebrity face to sell a camera proposition in sixty seconds. The script hangs on a single aspirational idea, carried by one hero talent rather than an ensemble, with product capability shown through what the character notices and frames. Production shape is a location led shoot with drone and gimbal work, a dedicated production designer, stylist and hair and makeup team, so budget sits in talent, locations and finish rather than crowd or effects. Tone is premium, clean and cinematic, with an original score and a careful grade doing much of the emotional lift.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea6d', 'thumsup-ft-allu-arjun', 'Thums Up', 'ThumsUp ft. Allu Arjun', '2024-12-26', 'Ogilvy', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=mL_xKhpmmow', 'TVC', 15, 'Telugu, Hindi', '["Beverages", "FMCG"]', 'launch', 'Single star delivering a direct-to-camera claim, built around one hero product moment rather than a story', '["bold", "cinematic", "dramatic", "high-impact"]', 'Allu Arjun', 'complex', '["vfx", "food"]', '[]', NULL, 'Useful when a brief needs a star signing announced as an event rather than a press release, in fifteen seconds. The script is one performer, one glass bottle and weather: a cap twist, a look up through the hair, two lines to camera, a long drink and a final foam spray at lens. Built entirely on a dark studio set with blue light, smoke, stone pillars and lightning added in post, so the world comes from grade and lighting rather than a location. Beverage product craft carried by a product specialist and food stylist, star silhouette held by costume, hair and make-up, sync sound for the actual voice, cut for Telugu and Hindi and timed to a film release.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea6b', 'wonderla', 'Wonderla', 'Wonderla', '2025-01-24', 'Talented', 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=JFlaq_fuA8E', 'TVC', 64, NULL, '["Travel", "Media, broadcast & entertainment", "Leisure & amusement parks"]', 'festive', NULL, '["festive", "upbeat", "family-friendly"]', NULL, 'standard', '["vfx"]', '[]', NULL, 'A useful reference for a festive campaign built around a regional occasion, in this case an Onam spot for an amusement park brand cut for both television and digital rotation. The production shape is a location shoot inside a park environment with a full art department building festive dressing, a line producer handling a South India schedule, and a CG and online pipeline supporting the finish, so it is a good comparison for scripts that need rides, crowds of visitors and set dressing to feel celebratory rather than documentary. Tone is warm, upbeat and family-facing, running just over a minute with a single clear festive idea.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea69', 'courtyard-by-marriott-2', 'Courtyard by Marriott', 'Courtyard by Marriott', '2025-02-24', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=bfcISSWoAMs', 'digital film', 30, NULL, '["Travel", "Hospitality"]', 'brand film', NULL, '["aspirational", "polished", "calm"]', NULL, 'standard', '[]', '[]', NULL, 'Useful as a reference for hospitality brand work shot on a live hotel property, in this case a business hotel in Navi Mumbai, where the room, lobby and public areas carry the story of effortless business travel. Also a reference for the companion cut model, where a second thirty second film is built from the same world and cast as the lead film and cut specifically for digital rotation, which keeps the shoot to a single property across one schedule. Tone is polished, calm and aspirational rather than dialogue heavy, so it suits scripts leaning on atmosphere, light and interior detail.', 0, 1, 'low', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea67', 'courtyard-by-marriott', 'Courtyard by Marriott', 'Courtyard by Marriott', '2025-02-24', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=PUg5QP1nLws', 'brand film', 30, NULL, '["Hospitality", "Travel"]', 'brand film', 'Observational day-in-the-life, following a modern business traveller through arrival, work and unwinding, told through small details and pacing rather than dialogue', '["warm", "cinematic", "calm", "aspirational"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for short hospitality brand work shot on location at a working hotel property, in this case a hill station resort, where the script has no dialogue and rides on observed detail: check in, a laptop open in a quiet corner, food, and the wind down at the end of the day. Production shape is a single property covered across many rooms and outdoor spaces within a tight thirty second cut, a small principal cast standing in for the modern business traveller, plus staff and background artistes. Mostly daylight and interiors lit for warmth. Tone is calm, premium and cinematic rather than salesy.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea65', 'kfc-boneless-2', 'KFC', 'Pick, Pop, Dip, Strip', '2025-02-24', 'FCB India', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=YkWjsfZllm4', 'TVC', 20, NULL, '["QSR & Food Service"]', 'product demo', 'a looping, glitch-like edit that repeats a four-step eating ritual so the viewer cannot tell whether the film has stuck or is deliberately cycling', '["playful", "snappy", "meme-able", "appetising"]', NULL, 'standard', '["food"]', '[]', NULL, 'A useful reference for a short-form quick service restaurant product film built around an eating ritual rather than a story. The script turns a four-beat action into a repeating loop, cut so the repetition reads as a deliberate glitch and carries the idea that one bite leads to another. Production shape is compact: controlled interior set work with strong food styling and product design, a small young cast, styled wardrobe and hair and makeup, and appetite-appeal lighting and grade doing much of the heavy lifting. Tone is playful, snappy and meme aware, pitched for both television and social cutdowns, and it sits as the companion piece in a two film campaign.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea63', 'kfc-boneless', 'KFC', 'Pick, Pop, Dip, Strip', '2025-03-24', 'FCB India', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=6UZY1qvy3B4', 'TVC', 20, NULL, '["QSR & Food Service"]', 'product demo', 'A four verb eating ritual built around a single piece of chicken, structured as repeated action beats and shot as tabletop craft', '["appetising", "playful", "punchy", "rhythmic"]', NULL, 'contained', '["food"]', '[]', NULL, 'A useful reference for short form quick service restaurant product work where the hero is the food itself and the idea lives in a repeatable eating ritual. The script turns four simple verbs into a rhythm, so the cut is beat driven and built for twenty seconds on television and social. Production shape is tight and studio led: a controlled tabletop setup with a food and product design focus, small cast handling, styling and grooming support, and heavy reliance on lighting, macro texture, grade and sound design to make the chicken look craveable. Tone is playful, appetising and meme friendly rather than narrative.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea61', 'wonderla-muthuswamy', 'Wonderla', 'Mind-Blown', '2025-03-24', 'Talented', 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=kZr7XE5ScGI', 'TVC', 67, NULL, '["Travel & leisure", "Media, broadcast & entertainment"]', 'festive', 'Character-led comic vignette built around a mind-blown reaction, with the exploding head emoji brought to life through CG', '["humorous", "playful", "exaggerated"]', NULL, 'complex', '["vfx"]', '[]', NULL, 'A useful reference for festive amusement park and leisure work where the idea hangs on a single visual gag delivered by one comic character. The script turns an emoji reaction into a literal effect, so the piece is built as a short performance vignette with a designed set or park environment, a production designer led look, and a CG house handling the hero effect and clean up. Production shape is compact in cast but needs storyboarded effects planning, controlled framing for the comp, and grade and online finishing. Tone is broad, playful and exaggerated, and it sits inside a trilogy so the treatment must repeat across films with a consistent comic rhythm.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea5f', 'campa-cola', 'Campa Cola', 'Campa Wali Zidd', '2025-03-24', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=lwXYoqwrmJk', 'TVC', 30, 'Hindi', '["Beverages", "FMCG"]', 'launch', 'Celebrity hero narrative built around grit: an action star pushes through injury to complete a dangerous stunt, with that stubbornness equated to the drink''s taste', '["gritty", "heroic", "determined", "high energy"]', 'Ram Charan', 'complex', '["stunts", "vehicle"]', '[]', NULL, 'A useful reference for a thirty second mass market beverage relaunch built around a star ambassador and a big ticket sporting window. The script runs on a single sustained idea of stubborn persistence: an action hero takes a hit on a stunt, refuses to stop and finishes the take, with the grit transferred straight onto the product. Production shape is star led and stunt driven, needing an action unit, safety cover, a designed set or backlot world, costume and continuity for injury detail, and a punchy music and grade treatment. Good comparison for launch films that need heroism, scale and a clean product payoff in half a minute.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea5d', 'britannia-good-day', 'Britannia', 'Good Day: Chai’s Better Half', '2025-03-24', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=mD2cvU9F8Xk', 'TVC', 48, NULL, '["FMCG", "food and beverage", "biscuits"]', 'brand film', 'product withheld, the biscuit is never shown and the idea is carried entirely by the chai ritual and brand memory', '["warm", "everyday", "nostalgic", "light"]', NULL, 'standard', '["food"]', '[]', NULL, 'A useful reference for a short FMCG positioning spot that sells a snack without ever putting the product on screen, leaning on brand memory and the familiar shape everyone already pictures. The script hangs on the daily tea ritual, so the production shape is intimate and prop led: everyday domestic and social settings, a small cast of ordinary people, tight food and beverage styling for steaming chai, and macro friendly lighting for texture. Day shoot, contained locations, no stunts or effects. Tone is warm, gently humorous and observational, closing on a category ownership line rather than a demo.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea5b', 'sealing-karmic-loops-in-rhythm-not-rush', 'First December Films', 'Sealing Karmic Loops in Rhythm, not Rush', '2025-06-19', NULL, 'Ganesh Pareek', 'ganesh-pareek', 'https://www.youtube.com/watch?v=AbptsYL_r2U', 'short', 342, NULL, '["Media, broadcast & entertainment"]', 'brand film', 'reflective long-form visual essay on ritual, rhythm and closure, built around the idea of completing life''s open loops slowly rather than in a hurry', '["reflective", "meditative", "calm", "introspective"]', NULL, 'standard', '[]', '[]', NULL, 'Useful when a client wants long-form, unhurried brand storytelling rather than a thirty second sell: a near six minute reflective piece built on ritual, rhythm and the idea of closing open loops. The shape is essayistic rather than plot driven, so it leans on atmosphere, observed detail, pacing and sound design to hold attention past the five minute mark. Read it as a tonal reference for meditative, interior films, self initiated in origin and made outside the regular commercial slate, where the writing is voice or text led and the production stays modest in cast and locations.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea59', 'peter-england-viv-richards', 'Peter England', 'The Gentleman’s League: League of Legends', '2025-07-08', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=GYt9GoXj1WI', 'TVC', 35, 'English', '["Fashion", "Apparel", "Retail"]', 'brand film', 'Documentary style celebrity reaction: a cricket legend is filmed in an unscripted moment receiving a tribute tee commemorating a historic World Cup win, framed within a mentorship idea of legends passing the game to younger players', '["emotional", "nostalgic", "warm", "reverent"]', 'Sir Vivian Richards, Harsha Bhogle', 'complex', '["sport", "vfx"]', '[]', NULL, 'A useful reference for a short apparel brand film built around a sporting icon rather than a product demo. The script hangs on a single unscripted reaction: a legend is handed a commemorative tee and the camera simply stays with him, with a commentator figure alongside to hold the conversation. Production shape is a celebrity entourage shoot with a dedicated entourage producer, casting for younger players, styling and art for a period sporting memento, steadicam coverage and a light CG and grade finish. Tone is warm, nostalgic and reverent, aimed at giving a merchandise collection an emotional centrepiece across a multi film campaign.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea57', 'peter-england-kapil-dev', 'Peter England', 'The Gentleman’s League: League of Legends', '2025-07-08', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=7s318_J38os', 'digital film', 35, NULL, '["Fashion", "Apparel & Retail"]', 'brand film', 'Unscripted celebrity reaction, a cricket legend responding on camera to a tribute tee commemorating the 1983 World Cup win, framed as a conversation with a commentator', '["nostalgic", "warm", "celebratory", "understated"]', 'Kapil Dev, Harsha Bhogle', 'complex', '["sport", "vfx", "music_led"]', '[]', NULL, 'A useful reference for short form fashion and apparel work built around a sporting icon, where the collection is introduced through a genuine, unscripted reaction rather than a written scene. The device is simple: a legend is shown a tribute garment commemorating a historic win, with a familiar commentator voice anchoring the exchange, so the product carries the emotion instead of a claim. Production shape is a controlled studio or single set build with styling, art direction and casting support, a compact crew, and a post pipeline including CG, grade, original music and sound design. Tone is nostalgic, warm and gentlemanly, cut tight to thirty five seconds.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea55', 'vivo-performance', 'VIVO', 'VIVO : PERFORMANCE', '2025-07-22', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=B6C3nGjMB7I', 'digital film', 61, NULL, '["Consumer Technology"]', 'product demo', 'Macro product craft cut to speed, building a performance story through precise lighting and rhythmic edit rather than dialogue or narrative characters', '["premium", "sleek", "kinetic", "tech-forward"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a flagship smartphone product demo built around performance rather than people. The script lives on macro tabletop craft, controlled studio lighting and speed-matched cutting that lets the edit rhythm carry the claim, so it suits briefs where the device itself is the hero and there is no cast or location story to tell. Also a reference for a launch handled as a set of companion films, with camera, design and performance treated as separate one-minute chapters that share a visual grammar. Tone is premium, precise and tech-forward, at around a minute in length.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea53', 'vivo-design', 'VIVO', 'VIVO : DESIGN', '2025-07-22', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=0pyMt1cN0m0', 'TVC', 52, NULL, '["Consumer Technology"]', 'product demo', 'Non-narrative product showcase built on macro detail shots of the device, with precise lighting and cutting paced to the edit rhythm rather than dialogue', '["premium", "sleek", "precise", "design-led"]', NULL, 'complex', '[]', '[]', NULL, 'A useful reference for a smartphone or premium hardware launch where the brief is to sell industrial design rather than a story. The script has no characters and no dialogue: it works entirely through macro product photography, controlled studio lighting on glass and metal edges, and speed-matched cutting that keeps a short runtime feeling crafted. Production shape is a controlled table-top or studio build with a specialist lighting and macro package, plus careful handling of hero devices. Also relevant when a client wants one film in a matched set of device films sharing a single visual grammar. Tone is cool, tactile and aspirational.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea51', 'vivo-camera', 'VIVO', 'VIVO : CAMERA', '2025-07-22', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=BEzVGCrOXfU', 'digital film', 62, NULL, '["Consumer Technology", "Smartphones"]', 'product demo', 'Product-led montage built on macro detail shots and speed-matched cutting to dramatise the camera system', '["sleek", "premium", "precise"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for a flagship smartphone launch where the camera system has to carry the story without dialogue or a celebrity face. The script leans on macro product craft, controlled lighting on glass and metal, and speed-matched cutting that keeps a sixty second runtime moving. Production shape is a tightly controlled table top and studio build with a specialist lighting and macro lens package rather than a large cast or location schedule, and it was delivered as one of three device films sharing a single visual grammar. Tone is sleek, premium and precise, aimed at buyers comparing camera specifications.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea4f', 'big-basket-chandu-ke', 'Big Basket', 'Big Basket Chandu Ke', '2025-10-01', 'Talented', 'Siddharth Sengupta', 'siddharth-sengupta', 'https://www.youtube.com/watch?v=k8j-1CsuK5w', 'TVC', 20, 'Hindi', '["Quick Commerce", "E-commerce"]', 'other', 'Two celebrity sisters perform the classic ''Chandu ke chacha'' tongue twister as a sung duet, with the rapid-fire wordplay standing in for a ten-minute delivery promise', '["playful", "musical", "nostalgic", "witty"]', 'Kareena Kapoor Khan, Karisma Kapoor', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for a short, celebrity-led quick commerce spot that has to sell a speed promise in twenty seconds without a product demo. The device is a familiar Hindi tongue twister rebuilt as a sung duet between two star sisters, so the writing lives in rhythm and delivery rather than plot. Production shape is compact but star heavy: a controlled set or single styled location, two principal artists, wardrobe and hair continuity, an original music track, mix and a tight grade and online finish. Tone is playful, nostalgic and warm, built for high recall and social talkability.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fca2e8c1e60255e2aea4d', 'big-basket-jello', 'Big Basket', 'Big Basket Jello', '2025-10-01', 'Talented', 'Siddharth Sengupta', 'siddharth-sengupta', 'https://www.youtube.com/watch?v=yqHK1XMjXxQ', 'TVC', 20, NULL, '["Quick Commerce", "E-commerce", "Grocery Delivery"]', 'brand film', 'Celebrity recreates her own iconic pop-culture movie moment as a nostalgia callback to dramatise a ten-minute delivery promise', '["nostalgic", "playful", "pop-culture", "light"]', 'Kareena Kapoor Khan', 'complex', '[]', '[]', NULL, 'A useful reference for a short, celebrity-led quick commerce spot that sells a speed of delivery promise through a pop-culture callback rather than a product demo. The script leans on a star recreating a moment audiences already know by heart, so the value sits in casting, costume and performance recall rather than plot. Production shape is compact: a twenty second cut, tight studio or single set build, small supporting cast, controlled lighting and a strong music and mix layer to land the nostalgia. Tone is playful, warm and knowing, and it works as part of a multi film celebrity campaign sharing one tagline.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c33', 'big-basket-lolo', 'Big Basket', 'Big Basket Lolo', '2025-10-01', 'Talented', 'Siddharth Sengupta', 'siddharth-sengupta', 'https://www.youtube.com/watch?v=gq9M5d3IUfg', 'TVC', 20, 'Hindi', '["Quick Commerce", "E-commerce"]', 'brand film', 'celebrity nostalgia callback, a star''s signature dance move and double role era replayed for a quick commerce proposition', '["nostalgic", "playful", "filmi", "upbeat"]', 'Karisma Kapoor', 'complex', '["music_led"]', '[]', NULL, 'A useful reference for short form celebrity led quick commerce work where the whole idea rests on a nineties film callback rather than a product demo. Twenty seconds, one female star recreating her own signature dance move and double role era, cut to a purpose built music bed so the choreography and the ten minute delivery promise land together. Production shape is compact but star dependent: controlled studio or set build, wardrobe and styling that reads as a period nod, tight schedule around a lead artist, and a music, edit and grade team carrying the nostalgia. Tone is warm, cheeky and unapologetically filmi. Also relevant as one film in a multi film sibling trilogy.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c31', 'pantaloons-durga-puja-2025', 'Pantaloons', 'Hok Tomar Agomon', '2025-10-01', 'Talented', 'Ishani Das', 'ishani-das', 'https://www.youtube.com/watch?v=bV7W9eM1MNE', 'digital film', 84, 'Bengali', '["Fashion", "Retail"]', 'festive', 'Reframes the festival''s central idea of the goddess''s arrival into each person''s own arrival, told through styled fashion vignettes that borrow festival motifs such as kaash flowers, boats and bamboo pandal scaffolding', '["celebratory", "warm", "aspirational", "lyrical"]', NULL, 'complex', '["multi_location", "water", "crowd"]', '[]', NULL, 'A useful reference for a festive fashion campaign built on regional cultural storytelling rather than product listing. The script turns the idea of homecoming and arrival into a personal, self-expression led theme, carried by styled vignettes where festival motifs like kaash grass fields, river boats and bamboo pandal scaffolding become fashion backdrops. Production shape is an ensemble cast across several outdoor and constructed locations, with heavy costume styling, production design and casting demands, plus water and crowd elements. Tone is warm, celebratory and lyrical, closer to a fashion film than a hard sell, and it suits brands wanting a regional language festive push with contemporary imagery.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c2f', 'vivo-x300-pro', 'VIVO', 'VIVO X300 PRO', '2026-01-27', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=XCDa8AVHW9M', 'digital film', 55, NULL, '["Consumer Technology", "Smartphones"]', 'launch', 'Product imaging capability dramatised through cinematic wild-India frames, built as an AI-integrated live action film tied to a National Geographic Creative Works collaboration', '["cinematic", "epic", "awe-struck", "premium"]', NULL, 'complex', '["vfx", "animals", "multi_location"]', '["Vivo: X300 Pro | Good Ads Matter Awards 2025 (Bronze)"]', 'Bronze, AI-Integrated Live Action Film, Good Ads Matter Awards 2025', 'A useful reference for flagship smartphone launch work where the camera is the hero and the proof has to look cinematic rather than demonstrative. The script leans on wilderness imagery from across India, cut as a short device film of under a minute, and blends live action photography with AI-generated and post-heavy imaging, so it suits briefs that need a hybrid pipeline, a strong post supervisor and design-led art direction. Production shape covers wildlife and landscape frames, styling and casting for human moments, and multiple looks stitched into one sequence. Tone is premium, awe-struck and epic, closer to a nature documentary trailer than a retail film.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c2d', 'vivo-x300', 'VIVO', 'VIVO X300', '2026-01-27', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=bN4DyCjzonI', 'TVC', 37, NULL, '["Consumer Technology", "Smartphones"]', 'launch', 'camera-first product storytelling built around the phone''s imaging capability, with styled featured cast and choreographed movement', '["aspirational", "sleek", "premium"]', NULL, 'standard', '["vfx"]', '[]', NULL, 'A useful reference for a short flagship smartphone launch spot where the camera system is the hero and the film has to sell imaging quality inside forty seconds. The device is camera-first storytelling: styled talent, designed sets and choreographed movement staged so each beat doubles as a demonstration of what the handset shoots. Production shape is crew-heavy rather than location-heavy, with a production designer, casting director, two costume stylists, a choreographer, featured cast and a CG studio for post enhancement, plus full colour and online finishing. Tone is premium, sleek and aspirational, cut tight for launch-day rollout across a flagship series.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c2b', 'cars24-mother-in-law-promise', 'Cars24', 'Family Promises: Mother-in-law Promise', '2026-02-20', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=S6RYgcQN8VY', 'TVC', 44, NULL, '["Automotive & Auto Marketplaces", "E-commerce"]', 'brand film', 'Comic escalation of a familiar Indian family vow, with the least likely promise-keeper of all standing behind the product guarantee', '["humorous", "warm", "bold", "conversational"]', NULL, 'standard', '["vfx", "vehicle"]', '[]', NULL, 'A useful reference for a short, single-minded advertising film that turns a category trust problem, in this case used-car quality, into a comic set piece by borrowing a familiar family vow and pushing it to its most improbable extreme. Built for a forty-five second cutdown with dialogue carrying the joke, so the writing and casting do most of the work. Production shape is compact: designed interiors, a small ensemble of family characters, a styled and made-up cast, a real vehicle in frame and light CG cleanup in post. Warm, wry, everyday-Indian-household tone that lands a hard policy commitment as a punchline. Also relevant for campaigns built as a set of matched films sharing one device.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c29', 'cars24-mother-promise', 'Cars24', 'Family Promises: Mother Promise', '2026-02-20', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=fjGNW2jl8Po', 'digital film', 41, 'Hindi', '["Automotive & Auto Marketplaces", "E-commerce"]', 'brand film', 'Real company CEO fronts the film and turns a familiar Indian family vow, maa kasam, into a literal brand policy commitment', '["wry", "warm", "direct", "deadpan"]', NULL, 'standard', '["vfx"]', '[]', NULL, 'A useful reference for short proposition films that dramatise a customer guarantee, in this case a lifetime warranty on used cars, by taking a colloquial family oath and converting it into hard policy. The device is a non actor spokesperson, the brand''s own India chief, delivering the promise straight to camera, so casting confidence, wardrobe and grooming carry as much weight as coverage. Production shape is compact: single controlled set with a production designer, one lead performer, day interior lighting, and a light CG and online pass for finishing. Tone is dry and warm rather than hard sell, built to run as one of three matching campaign films.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c27', 'cars24-sister-promise', 'Cars24', 'Family Promises: Sister Promise', '2026-02-20', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=VESWiOW-7vk', 'TVC', 44, 'Hindi', '["Automotive & Auto Marketplaces", "E-commerce"]', 'other', 'A familiar Indian family oath turned into a written policy guarantee: a real company CEO swears on his sister while the family cross-examines him through car windows, ending in a pull-back reveal that the cars are parked inside a living room set', '["comic", "warm", "deadpan", "conversational"]', NULL, 'standard', '["kids", "vehicle", "vfx"]', '[]', NULL, 'Useful when a brief needs terms and conditions, a warranty, a return window or a price guarantee turned into dialogue people will actually watch, rather than a voice-over reading policy. Also the reference for putting a founder or company head on camera and directing them so they never have to act, with the doubting relatives, a child and an older woman carrying the comedy around them. Production shape is contained but designed: a built living room interior with four cars parked inside it, all conversation shot over the shoulder through car windows, small family cast, day interior, one set shared across three films in a single job. Tone is warm Hindi family comedy under forty five seconds, caption led so it plays silent in feed.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c25', 'meta-d-cut', 'Meta', 'Cap Ka Suroor ft. Himesh Reshammiya (Director’s Cut)', '2026-02-20', 'Talented', 'Sukriti Tyagi', 'sukriti-tyagi', 'https://www.youtube.com/watch?v=PahY4FS_azk', 'digital film', 250, 'Hindi', '["Consumer Technology", "Social Media", "Small Business"]', 'brand film', 'Celebrity-led story in which a star''s search for the right product leads him to a small maker who promotes a custom design online, cut as an extended director''s version with original music', '["playful", "musical", "warm", "aspirational"]', 'Himesh Reshammiya', 'complex', '["music_led", "crowd", "multi_location"]', '["Meta: Cap Ka Suroor (Himesh) | Kyoorius Creative Awards 2026 (Blue Elephant) #2", "Meta: Cap Ka Suroor (Himesh) | Kyoorius Creative Awards 2026 (Blue Elephant)", "Meta: Cap Ka Suroor (Himesh) | Good Ads Matter Awards 2025 (Gold)"]', 'Two Blue Elephants at Kyoorius Creative Awards 2026 (Direction, Use of Original Music) and a Gold at Good Ads Matter Awards 2025 (Production Design), per the verified award list.', 'A useful reference for a long form platform brand film that turns a small business success story into entertainment, built around a music star playing himself and an original composition rather than a straight product explainer. The script shape moves between a performer''s world and a modest workshop, so it needs multiple built and dressed sets, a designed hero product, a stylist led star look with a full entourage on set, an ensemble supporting cast plus junior artistes for the performance beats, and a second unit. Tone is playful, affectionate and slightly larger than life, with production design and music doing much of the storytelling.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c23', 'google-gemini-passport-film', 'Google Gemini', 'Google Gemini Passport film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=D0ji_Meve_o', 'digital film', 22, 'Hindi', '["Consumer Technology", "Artificial Intelligence"]', 'product demo', 'single everyday use-case vignette, a first-time flyer using an AI assistant to untangle passport paperwork', '["warm", "everyday", "light", "reassuring"]', NULL, 'standard', '["multi_location"]', '[]', NULL, 'A useful reference for short product demo work that has to make an AI assistant feel useful in an ordinary Indian errand, here the paperwork panic of a first-time passport applicant. The script is a tight twenty-second vignette built on one relatable problem and one clean resolution, carried by a believable non-celebrity lead rather than a spokesperson. Production shape is modest and repeatable: everyday interiors and paperwork-heavy set dressing, small cast, day light, sync sound, with motion graphics and screen work handled in post. Worth citing when a brief needs one film in a multi-film, multi-language series where tone stays warm, light and reassuring across all versions.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c21', 'google-gemini-gst-film', 'Google Gemini', 'Google Gemini GST film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=KA8ty4_HQnA', 'digital film', 20, 'multilingual', '["Consumer Technology", "Artificial Intelligence", "Small Business"]', 'product demo', 'a small shopkeeper asks the AI assistant to make sense of GST filings, a single everyday problem solved on screen in twenty seconds', '["everyday", "warm", "practical", "reassuring"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for short form AI product demonstration work where an abstract capability has to be grounded in one ordinary Indian job to be done. The script takes a small shop owner wrestling with tax filings and resolves it in twenty seconds, so the writing has to land character, problem and payoff almost immediately. Production shape is contained: a shop interior style set with a small cast, real texture in production design and costume, sync sound and a motion graphics layer to show the interface. Made as one unit of a seven film series shot for scale across languages, so it also works as a reference for repeatable multi film packages with a consistent tone that stays warm, practical and unhurried.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c1f', 'google-gemini-creator-film', 'Google Gemini', 'Google Gemini Creator film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=BcaldQmB6Zk', 'digital film', 24, 'multi-language (Indian languages versions)', '["Consumer Technology", "Artificial Intelligence", "Technology"]', 'product demo', 'Slice-of-life problem-solve: a young content creator stuck on an idea uses the AI assistant to script, plan and post, with the product doing the work on screen', '["warm", "contemporary", "aspirational", "light"]', NULL, 'complex', '["animation"]', '[]', NULL, 'A useful reference for a short product demonstration film that dramatises an AI assistant inside an everyday Indian job to be done. The device is simple: a young creator hits a wall, turns to the assistant, and the product carries the story from idea to script to post, with motion graphics and interface work handling the demo beats. Production shape is a compact contemporary set with a small cast, art direction and styling for a creator''s world, sync sound and a licensed track. Built as one of seven linked films shot for scale and adapted across languages, so it suits a brief needing consistent tone and modular versioning within a tight cutdown.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c1d', 'google-gemini-fd-film', 'Google Gemini', 'Google Gemini FD film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=qmAn3krU3lk', 'digital film', 20, 'multilingual', '["Consumer Technology", "Artificial Intelligence"]', 'product demo', 'Everyday household money decision solved by asking the AI assistant, with the product acting as explainer inside a family conversation', '["warm", "everyday", "reassuring", "conversational"]', NULL, 'standard', '[]', '[]', NULL, 'A useful reference for short form technology use case films that dramatise a single ordinary decision, here a family weighing a fixed deposit while the assistant explains the choice in plain terms. Twenty seconds, one domestic interior, a small ensemble family cast, day interiors, with motion graphics handling the on screen product moments and sync sound keeping the dialogue natural. Built as one unit of a seven film set, so it is a good model for versioned, multi language rollouts where casting, production design and edit structure must repeat cleanly across films. Tone is warm, conversational and reassuring rather than jokey.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c1b', 'google-gemini-interview-film', 'Google Gemini', 'Google Gemini Interview film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=zpL_3LeRfUY', 'digital film', 24, 'multiple', '["Consumer Technology"]', 'product demo', 'single-protagonist slice of life, a job-seeker rehearsing for an interview with an AI assistant as prep partner, resolved in a short everyday vignette', '["warm", "aspirational", "everyday", "light", "reassuring"]', NULL, 'complex', '["multi_location"]', '[]', NULL, 'A useful reference for short-form product demonstration work that has to make an AI assistant feel useful in ordinary Indian life. The device is simple and repeatable: one relatable protagonist with a real jobs-to-be-done problem, in this case interview preparation, played out in a tight twenty-four second vignette with motion graphics carrying the on-screen product moment. Production shape is a small cast in domestic or workplace interiors with sync sound, casting-led performance, styling and production design, plus language versioning and a post pipeline built for a seven-film set shot together for scale. Tone is warm, contemporary and quietly aspirational rather than techy.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c19', 'google-gemini-galla-film', 'Google Gemini', 'Google Gemini Galla film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=HVOG0uVUkp0', 'digital film', 27, 'multiple Indian languages', '["Consumer Technology", "Artificial Intelligence"]', 'product demo', 'Everyday use-case vignette: a shopkeeper tallies the day''s cash box with AI assistance, showing the product solving a small, familiar task', '["warm", "observational", "everyday", "light"]', NULL, 'complex', '[]', '[]', NULL, 'A useful reference for short-form product demonstration work that grounds an AI or app feature in an ordinary Indian job to be done. The device is simple: a small trader closing his day''s accounts at the counter, with the assistant doing the arithmetic, so the benefit lands inside a familiar scene rather than a demo screen. Production shape is a single shop interior with a small cast, art direction and casting doing the heavy lifting on authenticity, plus motion graphics for the interface. Built as one of a seven-film set shot for scale and versioned across languages, so it also serves as a template for tight, repeatable multilingual batches in a warm, unhurried tone.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc8e78c1e60255e2a2c17', 'google-gemini-ac-film', 'Google Gemini', 'Google Gemini AC film', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=2SGSDbNp9jE', 'digital film', 25, 'Hindi', '["Consumer Technology", "Artificial Intelligence"]', 'product demo', 'everyday purchase dilemma solved by an AI assistant doing the research for a household', '["warm", "everyday", "relatable", "light"]', NULL, 'standard', '["multi_location"]', '[]', NULL, 'A useful reference for short product demonstration work that turns an abstract AI capability into a small domestic decision, in this case a family weighing up which air conditioner to buy while the assistant does the homework. The script shape is compact, twenty five seconds, built on a familiar household dilemma and a clear on screen product payoff supported by motion graphics for the interface. Production shape is a dressed home interior with a small ensemble cast, sync sound, casting led performances and a versioning plan across Indian languages. Also a reference for shooting one film as part of a larger multi film series with a consistent look and tone.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc7216d26e234f186585a', 'malaysia-airlines', 'Malaysia Airlines', 'Malaysian Airlines | Cricket at 30,000 Feet', '2026-05-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=xsVsTnNZeVk', 'TVC', 85, 'English', '["Aviation", "Travel", "Sports sponsorship"]', 'product demo', 'A child''s request to play cricket on a flight turns the cabin into a pitch, with the crew''s PA handset used as a commentary mic so each shot lands on a cabin feature', '["warm", "comedic", "celebratory", "family"]', 'Rohit Sharma, Hardik Pandya, Trent Boult', 'complex', '["vfx", "kids", "crowd", "sport", "food", "music_led"]', '[]', '141 million views on the Malaysia Airlines YouTube channel by September 2026; coverage in afaqs, Business Standard, The Tribune, Storyboard18 and The Star', 'A useful reference for a sponsorship activation that has to do more than put a logo on a jersey, and for hiding a product demonstration inside a comedy. The script uses a child asking to play, a public address handset turned into a commentary mic, and seven cabin features scored as cricket beats, so every seat, screen, bed and snack earns its place in the joke. Production shape is a built business class cabin set with authentic uniforms, styled food and a full cast of passengers, three international cricketers available for only a short in season window, aircraft and stadium visual effects, plus a parallel socials unit shooting vertical content. Warm, funny, fan first rather than star first.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a5fc6db92237bdf910da131', 'cipcal-500', 'Cipla Cipcal 500', 'Cipcal 500', '2026-02-15', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/watch?v=6N4tFmK1ZWo', 'TVC', 69, 'Hindi', '["Healthcare, pharma & wellness"]', 'brand film', 'revival of a beloved sitcom character whose catchphrase is reframed as a health cue', '["nostalgic", "warm", "humorous", "reassuring"]', 'Supriya Pathak', 'complex', '[]', '[]', NULL, 'A useful reference for low-interest health and supplement categories that need a pop culture hook rather than a clinical pitch. The script borrows a much loved television character and turns her signature dialogue into a symptom prompt, aimed squarely at women over thirty who ignore everyday fatigue. Production shape is a talent led shoot with a well known actor and her entourage, a small supporting cast, built interior sets with a designed domestic look, styling and prosthetic free character recreation, sync sound and an original music bed. Comparable when a brief asks for warm sitcom nostalgia, comic timing and a clear health message inside seventy seconds.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53da60c034cb7d550c6c7a', 'razorpay', 'Razorpay', 'Razorpay', '2025-06-10', 'Talented', 'Shivang Monga', 'shivang-monga', 'https://www.youtube.com/playlist?list=PLEU7bwSIhxZM', 'series', NULL, NULL, '["Banking & Fintech", "technology", "payments"]', 'brand film', 'Real startup founders rather than actors front the films, with each founder''s business becoming the story across a run of short spots built for cricket ad breaks', '["celebratory", "aspirational", "authentic", "energetic"]', NULL, 'complex', '["vfx", "multi_location", "sport"]', '["Beauty Tips by Reshma: AMES 2016 (Bronze) #2", "Beauty Tips by Reshma: Cannes Lions 2016 (Finalist) #3", "Meta: Cap Ka Suroor (Himesh) | Kyoorius Creative Awards 2026 (Blue Elephant)"]', NULL, 'A useful reference for a large volume brand campaign built as many short films rather than one hero spot, made to run across ad breaks during a cricket season. The device is casting real founders and business owners as the faces of the brand instead of actors, so the shape of the shoot involves non professional talent, multiple set ups and a repeatable visual system that holds together across dozens of cuts. An AI studio sits in the pipeline alongside a full producing team, so it also works as a template for scale, turnaround and cost control. Tone is warm, proud and celebratory of builders.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53da26e2850658bd242f4a', 'youtube', 'YouTube', 'Youtube', '2026-07-07', NULL, 'Ganesh Pareek', 'ganesh-pareek', NULL, 'series', NULL, 'Multi-language (Hindi and regional Indian languages)', '["Consumer Technology", "Media, broadcast & entertainment"]', 'launch', 'Creator-led platform launch blitz, one line adapted across languages, plus music-artist tie-in films and a dance trend series', '["energetic", "youthful", "pop culture", "fast-cut"]', 'Badshah', 'complex', '["music_led", "multi_location"]', '[]', NULL, 'A useful reference for a platform or app launch that has to land in many languages at once rather than as a single hero film. The shape is a volume campaign: fifteen-plus short films built around creators and a repeatable line adapted region by region, with music-artist tie-in cuts and a dance trend series running alongside. Expect multiple set-ups and looks, a rotating cast of creators and talent, quick turnarounds at platform speed and a directing team splitting the slate. Tone is young, energetic and pop culture literate, cut fast and built for vertical, social-first viewing.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d9f0bdbcc760ce1e7482', 'meta', 'Meta', 'Meta', '2026-02-08', NULL, 'Sukriti Tyagi', 'sukriti-tyagi', 'https://www.youtube.com/watch?v=PahY4FS_azk', 'digital film', 250, 'Hindi', '["Consumer Technology", "Social Media Platform", "Advertising Technology"]', 'product demo', 'two parallel worlds, a struggling lane shop and a superstar, intercut and finally joined by the product; celebrity playing a heightened version of himself', '["comic", "warm", "affectionate satire", "feel-good", "aspirational"]', 'Himesh Reshammiya', 'complex', '["crowd", "multi_location", "music_led", "night"]', '[]', NULL, 'A useful reference for explaining a platform feature through story rather than a screen recording, where the product tap is the turning point of a small business tale. The script runs two worlds side by side, a cluttered cap shop built on set in a Mumbai lane and a superstar''s expanding universe of rehearsal room, poolside, bedroom, tour bus and a full stadium stage, then lets them meet in the last act. Shows a celebrity playing a comically heightened version of himself with everyone around him straight faced, a hero prop repeated across a large crowd, second unit support, custom music and a four minute run time that holds as entertainment.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d9b59b911817ae131b17', 'jio-hotstar', 'JioHotstar', 'Jio hotstar | History Repeat Karenge T20 2026', '2025-02-14', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=4_9WEyQjOEs', 'brand film', 47, 'Hindi', '["Media, broadcast & entertainment", "Sports broadcasting", "Streaming"]', 'launch', 'Direct-to-camera address from the national captain standing inside the crowd, naming history itself as the opponent, with a two-verb line that turns on its second meaning', '["stirring", "defiant", "patriotic", "confident", "big-stage"]', 'Rohit Sharma', 'complex', '["crowd", "sport", "night"]', '[]', NULL, 'Useful when a sports broadcaster needs a tournament launch film built on an idea rather than a fixture list. The device is a single unbroken address from a national cricketer who speaks plainly rather than acts, naming rival teams and then an unnamed opponent, with records counted off on his fingers. Production shape is one stadium worked two ways: tight crowd coverage with hundreds of extras in team shirts and floodlights at dusk, plus an aerial of a full bowl with the campaign line spelled out in the stands. Archive footage and a trophy pass are cut in. Tone is defiant, patriotic and built for a hard broadcast date, with a shorter cut alongside.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d96fe2850658bd241551', 'swiggy', 'Swiggy', 'Swiggy', '2024-09-02', NULL, 'Nitin Menon', 'nitin-menon', 'https://www.youtube.com/watch?v=K78sOK1ythc', 'TVC', 30, 'Hindi', '["Quick Commerce", "QSR & Food Service", "Food Delivery"]', 'festive', 'A single visual exaggeration carried by deadpan reaction: a fairy-lit battle tank rolls down a Diwali lane, scattering a stage performance, and the family treats it as a slightly larger than usual party problem until the bulk-order delivery vehicle arrives as the punchline', '["deadpan", "comic", "festive", "warm", "understated"]', NULL, 'complex', '["night", "crowd", "vehicle", "vfx"]', '[]', NULL, 'A useful reference for a festive thirty second spot that has to explain a new bulk delivery service without listing features, using one oversized visual gag instead. The production shape is a single dressed old Mumbai lane at night, art directed with a bulb framed stage, strings of lights, a wooden balcony and a family dining room window so one location covers every angle. A real tank is driven through the set with a second unit covering crowd, policeman and balcony reactions, plus a branded electric three wheeler for the payoff. Ensemble cast playing comedy straight, warm bulb lit grade, light CG support and a fast turnaround timed to launch and festival week.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d92549f8b04e5347fdd3', 'knorr-x-netflix', 'Knorr x Netflix', 'KNORR x NETFLIX', '2024-12-15', 'Talented', 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=mv3JrA3mDus', 'digital film', 90, 'Hindi', '["FMCG", "Media, broadcast & entertainment"]', 'launch', 'Product demonstration staged as a game with rules inside a licensed entertainment world, with a masked authority figure unmasked as a star cameo in the final beat', '["high stakes", "playful", "deadpan", "suspenseful"]', 'Gulshan Grover', 'complex', '["crowd", "food", "music_led"]', '[]', '60.6 million views for the 40-second cut and 307,000 for the full film on the Knorr India channel by September 2026; Indian Television reported 10 million views in nine days; shortlisted for Best Branded Content at the Festival of Media Global 2025', 'A useful reference for a limited-edition launch built on a licensed entertainment property, where the borrowed world is played straight rather than turned into a trailer. The script writes the product demonstration as a game with rules and a countdown, so the taste claim is never spoken, and holds a star cameo behind a mask until the final line. Production shape is a single built arena set with tiled walls, floor markings and a hanging prize container, a large costumed crowd where each extra needs one readable close-up, choreography and action direction for the freeze beat, food styling, jib and Steadicam work, plus a separate socials unit on the same set. Sound design carries the middle stretch with no dialogue.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d8d4e08d3e470d324621', 'malaysian-airlines', 'Malaysia Airlines', 'Malaysian Airlines', '2026-05-07', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=xsVsTnNZeVk', 'digital film', 85, NULL, '["Aviation", "Travel", "Sport"]', 'brand film', 'Celebrity cricketers playing a game of cricket inside an aircraft cabin at cruising altitude, using the airline environment as the playing field', '["playful", "aspirational", "light-hearted", "premium"]', 'Rohit Sharma, Hardik Pandya, Trent Boult', 'complex', '["sport", "vehicle", "crowd"]', '[]', NULL, 'A useful reference for an airline or travel brand partnering with a sports team, where the brief is to turn cabin service into entertainment rather than list features. The device is simple and repeatable: put well known players inside the aircraft interior and let a game break out among the seats and aisles, with cabin crew and fellow passengers reacting. Production shape is a controlled aircraft cabin build or grounded aircraft, tight lens choices in a narrow set, restricted celebrity availability across a short shoot window, and a supporting cast of passengers. Tone is playful, warm and premium, sitting close to eighty five seconds for digital.', 0, 0, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53d884cbeb7e4ee69acb78', 'zee-x-fifa', 'ZEE', 'ZEE X FIFA', '2026-01-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://youtu.be/PXlhbTPJCZU', 'digital film', 68, 'Hindi (Hinglish), with versions in English, Bangla, Malayalam, Tamil and Telugu', '["Media, broadcast & entertainment", "Sports broadcasting", "Streaming"]', 'launch', 'Montage of many Indian living rooms watching the same match, each household in a different national kit, cut with real tournament footage and resolved on a Hinglish type line', '["celebratory", "warm", "high energy", "fan-first", "humorous"]', NULL, 'complex', '["crowd", "night", "multi_location", "kids", "music_led", "sport", "vehicle"]', '[]', '26 million views on the ZEE5 channel by September 2026, with countdown cutdowns passing 28 to 35 million views each.', 'A useful reference for a broadcast or streaming launch that has to go from brief to air in under a week, and for selling a sporting event without any access to the sport itself. The script device is a tour of a dozen households, each dressed as a different India and a different national kit, all reacting to the same screen, cut with licensed match footage and landing on a Hinglish line in big type. Production shape is many built living room sets, around forty performers including children, choreographed and coached reactions on cue, night interiors lit by television, a car interior and a city skyline. Tone is warm, funny and openly partisan.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c408b89f6b6fe878d35d', 'muscle-blaze', 'Muscle Blaze', 'MuscleBlaze: The Call', '2023-08-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=heWfGiGMJm8&t=1s', 'anthem', 131, 'Hindi, English', '["Healthcare, pharma & wellness", "Sportswear & Athletic", "Sports nutrition"]', 'brand film', 'voice-over led anthem scored to original music, following a small ensemble of athletes', '["motivational", "gritty", "aspirational"]', NULL, 'complex', '["animals", "music_led", "sport"]', '[]', NULL, 'A useful reference for a sports nutrition or fitness brand anthem that runs past two minutes and carries the brand on voice-over and original score rather than dialogue. The script follows a small cast of three athletes through training, so it needs casting for physique, styling and grooming teams, and a location plan that can carry several training environments. A trained dog features, which adds a handler and slower coverage on set. Shot with gimbal and operator support for movement-heavy coverage, delivered in Hindi and English voice-over versions. Tone is gritty, driven and aspirational, built to be cut to music.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c3d6d2f5baa54279d39c', 'gemini', 'Google Gemini', 'Google Gemini India films', '2026-05-15', NULL, 'Ronak Chugh', 'ronak-chugh', 'https://www.youtube.com/watch?v=zpL_3LeRfUY', 'series', 24, 'Hindi', '["Consumer Technology"]', 'product demo', 'One worry, one spoken conversation with the assistant, one press: each film states an everyday problem in a single breath and lets the phone answer aloud, with on-screen captions carrying the demo', '["conversational", "warm", "naturalistic", "reassuring", "everyday"]', NULL, 'complex', '["multi_location", "night"]', '[]', NULL, 'A useful reference for explaining a technology or AI product through recognisable use cases rather than features, and for building a seven-part series on one repeatable structure. Each piece runs twenty to twenty-seven seconds, sits in a single location with its own palette, from a blue night bedroom to a chandelier-hung lamp shop, a saree shop, a sunlit flat, a kitchen table and a tailor''s counter, and turns on dialogue in Hindi with a Gujarati passage. Cast for authenticity across different Indian households and small businesses, with a familiar Hindi film face anchoring three chapters. Voice assistant shown as conversation, captions carrying the demonstration, warm and unhurried, built for pre-roll.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c3b29363359153f92a04', 'big-basket', 'Big Basket', '10 minutes means BigBasket', '2025-10-01', NULL, 'Siddharth Sengupta', 'siddharth-sengupta', 'https://www.youtube.com/watch?v=yqHK1XMjXxQ', 'series', 20, NULL, '["Quick Commerce", "E-commerce"]', 'product demo', 'Trilogy of short comic vignettes built around the ten-minute delivery promise, with two celebrity sisters playing off each other and wordplay nicknames as the hook', '["comic", "light", "banter-led"]', 'Kareena Kapoor, Karisma Kapoor', 'complex', '["multi_location"]', '[]', NULL, 'A useful reference for a quick commerce speed promise handled as a set of very short comic films rather than one long story. The device is a trilogy of twenty second vignettes sharing one line and one visual world, each hung on a nickname gag, with two high profile film stars playing sisters and trading banter. Production shape is star talent management, tight scheduling to bank three spots efficiently, controlled set or apartment style interiors, small supporting cast and a wardrobe and styling load that matches celebrity expectations. Tone is glossy, playful and quotable, built for repeat exposure across a campaign burst.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c37fc6b8791b2145b4a0', 'hrx', 'HRX', 'HRX ft. Hrithik Roshan', '2019-06-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=9sHXJsWrZME', 'TVC', 63, NULL, '["Sportswear & Athletic", "Fashion", "Fitness"]', 'brand film', 'celebrity founder fronting his own brand in a performance led training piece', '["intense", "aspirational", "energetic"]', 'Hrithik Roshan', 'complex', '["sport"]', '[]', NULL, 'A useful reference for a founder led sportswear or athleisure brand campaign built around a single star talent, where the celebrity is both the face and the owner of the label. The script leans on athletic performance rather than dialogue, with training and movement carrying the message, so it suits briefs that need a high intensity body led film cut to around a minute. Production shape is star talent scheduling, a controlled shoot environment with hard styled lighting and wardrobe, and coverage built for a fast cut. Tone is intense, aspirational and driven, aimed at fitness and youth audiences.', 0, 1, 'medium', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c330347fb3edadbe3e22', 'kfc', 'KFC', 'KFC Boneless', '2025-03-01', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=6UZY1qvy3B4', 'TVC', 20, NULL, '["QSR & Food Service"]', 'product demo', 'a four step eating ritual, pick, pop, dip and strip, used as a repeatable mnemonic that structures the cut around the product', '["appetising", "playful", "energetic"]', NULL, 'standard', '["food"]', '[]', NULL, 'A useful reference for short form quick service restaurant work where the product itself carries the spot and the script is built on a snappy verb led ritual, in this case a four beat eating sequence that doubles as the campaign line. Production shape is tight and controlled: a twenty second television cut driven by food craft, hero product photography, close hand and mouth action, a food styling and art led set rather than location coverage, with a dedicated production designer, stylist and hair and makeup for the on camera talent. Tone is bright, playful and appetite forward, with music and sound design cut to the rhythm of each step.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c30946434332b3d12e6a', 'myntra', 'Myntra', 'Myntra: India’s Fashion Expert', '2021-05-01', NULL, 'Shivin & Sunny', NULL, 'https://www.youtube.com/watch?v=8yU7RUIRFY0', 'series', 40, NULL, '["E-commerce", "Fashion"]', 'brand film', 'Celebrity-fronted series built around a fashion expert positioning, with a cricket season film cut for the IPL window', '["aspirational", "stylish", "upbeat", "confident"]', 'Hrithik Roshan, Kiara Advani, Vijay Deverakonda, Dulquer Salmaan', 'complex', '["multi_location", "sport"]', '[]', NULL, 'A useful reference for a fashion or e-commerce brand positioning campaign that needs several star-led films cut from one shoot plan, plus a cricket season edit timed to the tournament window. The device is simple: big-name faces carrying a fashion authority line across Hindi and southern markets, so each film has to hold on wardrobe, styling and personality rather than plot. Production shape is multi-city with separate line production and art teams, dedicated stylist and hair and make-up, controlled sets and clean forty second cutdowns. Tone is aspirational, stylish and upbeat, with a confident tongue-in-cheek edge.', 0, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO works (id, slug, client, campaign, year, agency, director, director_slug, video_url, format, duration_seconds, language, industry, brief_type, narrative_device, tone, celebrity, complexity, flags, awards, outcome, reference_for, has_case_study, is_published, confidence, indexed_at) VALUES ('6a53c28ed00e55970eae7fed', 'vivo', 'VIVO', 'Vivo X Series', '2026-01-15', NULL, 'Atul Kattukaran', 'atul-kattukaran', 'https://www.youtube.com/watch?v=XCDa8AVHW9M', 'digital film', 55, 'English', '["Consumer Technology", "Mobile Handsets"]', 'launch', 'Single protagonist travels out of the city with friends and discovers each camera feature in the order a real user would, with the phone''s own viewfinder images and typed AI prompt carrying the demonstration', '["aspirational", "warm", "understated", "lifestyle"]', NULL, 'complex', '["multi_location", "music_led", "animals"]', '[]', NULL, 'Useful reference for a flagship camera phone launch that has to prove hardware in use rather than in a render. The script hangs a spec sheet on a weekend trip: a young photographer and three friends leave a city flat for a pine forest, a windy hilltop and a valley, so long focal lengths and a screw on telephoto extender mean something you can actually see. Features are demonstrated on camera, including a side by side zoom comparison, close ups of the grip and mount, and an AI video request shown as a typed prompt and a played back result. Phone captured frames with watermarks sit inside the film. Music led, no voice over, daylight exteriors, small cast, warm and quietly confident.', 1, 1, 'high', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('ronak-chugh', 'Ronak Chugh', 'Ronak Chugh is a director working with 1st December Films. He directed the seven-film Google Gemini campaign (2026), which grounds AI in everyday Indian moments from GST filings to passport queues, and the Malaysia Airlines ''Cricket at 30,000 Feet'' film with the Mumbai Indians. His wider body of work spans commercials, music videos and narrative film, including ''The Unfiltered History Tour'' for Vice, among the most awarded campaigns in Indian advertising history, as well as campaigns for Swiggy, Uber and UCB.', '[{"work_id": "6a5fc8e78c1e60255e2a2c23", "slug": "google-gemini-passport-film", "client": "Google Gemini", "campaign": "Google Gemini Passport film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c21", "slug": "google-gemini-gst-film", "client": "Google Gemini", "campaign": "Google Gemini GST film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1f", "slug": "google-gemini-creator-film", "client": "Google Gemini", "campaign": "Google Gemini Creator film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1d", "slug": "google-gemini-fd-film", "client": "Google Gemini", "campaign": "Google Gemini FD film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c1b", "slug": "google-gemini-interview-film", "client": "Google Gemini", "campaign": "Google Gemini Interview film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c19", "slug": "google-gemini-galla-film", "client": "Google Gemini", "campaign": "Google Gemini Galla film", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c17", "slug": "google-gemini-ac-film", "client": "Google Gemini", "campaign": "Google Gemini AC film", "year": "2026"}, {"work_id": "6a53c3d6d2f5baa54279d39c", "slug": "gemini", "client": "Google Gemini", "campaign": "Google Gemini India films", "year": "2026"}]', 'Best suited to short form product demonstration scripts that have to make a technology feature legible inside an ordinary Indian household or small business, in twenty to thirty seconds. He works from casting-led performance, dressed real interiors, sync sound dialogue and a motion graphics layer carrying the interface beats. Particularly useful on multi-film packages shot together for scale, where tone, palette and edit structure must repeat cleanly across seven films and several language versions.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('shivang-monga', 'Shivang Monga', 'Shivang Monga is a director at 1st December Films who brings a sharp eye for everyday Indian behaviour: humour, warmth and performance-driven storytelling. His work across leading brands including CARS24, IGP, Britannia Good Day, Titan, BigBasket, Cipla and Razorpay reflects a strong instinct for capturing simple human moments that connect instantly and leave a lasting impression. As part of the creative team at 1st December Films, Shivang continues to craft culture-rich, character-led and sharply observed films that combine authentic storytelling with strong visual execution.', '[{"work_id": "6a8596924735e02c4ea49f64", "slug": "razorpay-cheq", "client": "Razorpay", "campaign": "Cheq", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f62", "slug": "razorpay-phool", "client": "Razorpay", "campaign": "Phool", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f60", "slug": "razorpay-traya", "client": "Razorpay", "campaign": "Traya", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f5e", "slug": "razorpay-go-desi", "client": "Razorpay", "campaign": "Go Desi", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f5c", "slug": "razorpay-id-fresh", "client": "Razorpay", "campaign": "iD Fresh", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f5a", "slug": "razorpay-magicpin", "client": "Razorpay", "campaign": "Magicpin", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f58", "slug": "razorpay-inde-wild", "client": "Razorpay", "campaign": "Inde Wild", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f56", "slug": "razorpay-akasha-air", "client": "Razorpay", "campaign": "Akasha Air", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f54", "slug": "razorpay-blue-tokai", "client": "Razorpay", "campaign": "Blue Tokai", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f52", "slug": "razorpay-shaadi-com", "client": "Razorpay", "campaign": "Shaadi.com", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f50", "slug": "razorpay-lahori-zeera", "client": "Razorpay", "campaign": "Lahori Zeera", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f4e", "slug": "razorpay-avimee-herbal", "client": "Razorpay", "campaign": "Avimee Herbal", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f4c", "slug": "razorpay-culture-circle", "client": "Razorpay", "campaign": "Culture Circle", "year": "2026"}, {"work_id": "6a8596924735e02c4ea49f4a", "slug": "razorpay-the-sleep-company", "client": "Razorpay", "campaign": "The Sleep Company", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c2b", "slug": "cars24-mother-in-law-promise", "client": "Cars24", "campaign": "Family Promises: Mother-in-law Promise", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c29", "slug": "cars24-mother-promise", "client": "Cars24", "campaign": "Family Promises: Mother Promise", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c27", "slug": "cars24-sister-promise", "client": "Cars24", "campaign": "Family Promises: Sister Promise", "year": "2026"}, {"work_id": "6a5fc6db92237bdf910da131", "slug": "cipcal-500", "client": "Cipla Cipcal 500", "campaign": "Cipcal 500", "year": "2026"}, {"work_id": "6a5fca2e8c1e60255e2aea5d", "slug": "britannia-good-day", "client": "Britannia", "campaign": "Good Day: Chai’s Better Half", "year": "2025"}, {"work_id": "6a53da60c034cb7d550c6c7a", "slug": "razorpay", "client": "Razorpay", "campaign": "Razorpay", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea85", "slug": "igp-3", "client": "IGP", "campaign": "Amazing Gifts, Samay Par", "year": "2024"}, {"work_id": "6a5fca2e8c1e60255e2aea81", "slug": "igp-2", "client": "IGP", "campaign": "Amazing Gifts, Samay Par", "year": "2024"}, {"work_id": "6a5fca2e8c1e60255e2aea71", "slug": "igp", "client": "IGP", "campaign": "Amazing Gifts, Samay Par", "year": "2024"}]', 'Send him scripts that live in the everyday and need volume: batched merchant or customer series where a dozen fifteen second cuts must share one template and still feel distinct, festive spots built on period pastiche where design, casting and costume carry the gag, and dialogue-led family comedy that turns a warranty or policy line into something watchable. He is a safe pair of hands with non-actors, founders and real business settings, working on contained interiors and tight schedules.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('nitin-menon', 'Nitin Menon', 'Nitin Menon is a director working with First December Films. His credits include Swiggy XL, Wonderla''s festive series (Muthuswamy, Dussehra, Onam) and the Schweppes film with Jazzy B.', '[{"work_id": "6a5fca2e8c1e60255e2aea6b", "slug": "wonderla", "client": "Wonderla", "campaign": "Wonderla", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea61", "slug": "wonderla-muthuswamy", "client": "Wonderla", "campaign": "Mind-Blown", "year": "2025"}, {"work_id": "6a64b868eee3b1cb44b9332f", "slug": "schweppes-x-jazzy-b", "client": "Schweppes", "campaign": "Schweppes x Jazzy B", "year": "2024"}, {"work_id": "6a5fca2e8c1e60255e2aea83", "slug": "swiggy-xl", "client": "Swiggy", "campaign": "Swiggy XL", "year": "2024"}, {"work_id": "6a5fca2e8c1e60255e2aea73", "slug": "wonderla-2", "client": "Wonderla", "campaign": "Wonderla", "year": "2024"}, {"work_id": "6a53d96fe2850658bd241551", "slug": "swiggy", "client": "Swiggy", "campaign": "Swiggy", "year": "2024"}]', 'Best suited to comedy driven scripts where a single visual gag or a well cast performer carries the whole idea, particularly festive briefs that need a story rather than decoration. Comfortable with amusement park and location shoots involving rides, crowds and night processions, practical costume builds, and art directed sets that stand in for a whole street. Also a fit for music led celebrity spots and thirty second food delivery work with product framing, feed pacing and light CG support.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('shiv-parameswaran', 'Shiv Parameswaran', 'Shiv Parameswaran is a director working with First December Films. He directed Google''s #SearchSomethingNew campaign: Kaali Peeli, Matchbox, Ganji Chudail and Horn OK Please, which won a Kyoorius Baby Blue Elephant for Film Craft / Editing, as well as the XYXX UNDIE-PENDENCE and Ather films.', '[{"work_id": "6a64b36e59e34184ae1fb886", "slug": "google-search-something-new", "client": "Google", "campaign": "Search Something New", "year": "2024"}, {"work_id": "6a5fcb0b9eb2ac28337b75df", "slug": "ather-director-s-cut", "client": "Ather Energy", "campaign": "Ather (Director’s Cut)", "year": "2022"}]', 'Best suited to short form work where the idea is carried by cutting and post rather than dialogue or performance. Strong on multi film sets built to a common rhythm, associative edits that jump between observed detail and product, and fifteen to twenty second running times that still need real craft. Comfortable with small casts, art directed props, vehicle work, CG support and originally directed music. Sensible choice for tech, search or premium urban product briefs needing a modern, design led finish.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('sukriti-tyagi', 'Sukriti Tyagi', 'Sukriti Tyagi is a director working with 1st December Films, credited on Meta''s ''Cap Ka Suroor'' film with Himesh Reshammiya (2026), winner of Kyoorius Blue Elephants for Direction and for Use of Original Music, and a Good Ads Matter Gold for Production Design.', '[{"work_id": "6a5fc8e78c1e60255e2a2c25", "slug": "meta-d-cut", "client": "Meta", "campaign": "Cap Ka Suroor ft. Himesh Reshammiya (Director’s Cut)", "year": "2026"}, {"work_id": "6a53d9f0bdbcc760ce1e7482", "slug": "meta", "client": "Meta", "campaign": "Meta", "year": "2026"}]', 'Best suited to long form branded storytelling where a product or feature has to land as narrative rather than demonstration. Comfortable with celebrity casting played for comedy, including talent appearing as a heightened version of themselves, and with the logistics that brings, entourages, stylists, ensemble support and crowd work. Strong on scripts that run two worlds in parallel and converge late, needing built and dressed sets, a designed hero prop, original music and second unit. Tone is warm, playful and slightly heightened.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('ishani-das', 'Ishani Das', 'Ishani Das is a director working with First December Films, credited on the Pantaloons Durga Puja 2025 campaign, praised for capturing Bengali festive culture authentically.', '[{"work_id": "6a5fc8e78c1e60255e2a2c31", "slug": "pantaloons-durga-puja-2025", "client": "Pantaloons", "campaign": "Hok Tomar Agomon", "year": "2025"}]', 'Best suited to festive and fashion work where culture carries the story and product stays in the styling. She handles ensemble casts, multiple outdoor and built locations, and scripts that lean on costume, production design and regional detail rather than dialogue or demonstration. Comfortable with water, crowd and scaffolding setups. Bring her scripts in Bengali or other regional languages that need warmth, rhythm and a lyrical vignette structure, closer to a fashion piece than a sales film.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('siddharth-sengupta', 'Siddharth Sengupta', 'Siddharth Sengupta is a director working with First December Films, credited on the Big Basket campaign trilogy: Chandu Ke, Lolo and Jello (2025).', '[{"work_id": "6a5fca2e8c1e60255e2aea4f", "slug": "big-basket-chandu-ke", "client": "Big Basket", "campaign": "Big Basket Chandu Ke", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea4d", "slug": "big-basket-jello", "client": "Big Basket", "campaign": "Big Basket Jello", "year": "2025"}, {"work_id": "6a5fc8e78c1e60255e2a2c33", "slug": "big-basket-lolo", "client": "Big Basket", "campaign": "Big Basket Lolo", "year": "2025"}, {"work_id": "6a53c3b29363359153f92a04", "slug": "big-basket", "client": "Big Basket", "campaign": "10 minutes means BigBasket", "year": "2025"}]', 'He is a sound fit for short form, celebrity-fronted work where the idea has to land in twenty seconds without a product demo. Think rhyme, banter, nickname gags, song and dance callbacks to older Hindi cinema, and performance built on recall rather than plot. He handles multi film bursts that share one line and one visual world, shot efficiently on controlled sets around a lead artist''s schedule, with music, wardrobe and styling doing much of the storytelling. Tone stays playful, warm and knowing.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('ganesh-pareek', 'Ganesh Pareek', 'Ganesh Pareek is partner, executive producer and creative director at First December Films, and winner of the Cannes Gold Lion and Cannes Glass Lion. He is counted among the top television commercial producers in the world. Trained at DDB and then Mudra Calcutta, he has produced virtually the entire First December Films slate, from Nike ''Make Every Yard Count'' and ''Beauty Tips by Reshma'' to Google, Meta, Vivo, KFC and Star Sports. In 2023 he directed the feature film Manu. He teaches film appreciation at the Film and Television Institute of India (FTII) Pune and at Xavier Institute of Communications (XIC) Mumbai, and has shared stages with Grammy-winning musicians as an expert speaker.', '[{"work_id": "6a53da26e2850658bd242f4a", "slug": "youtube", "client": "YouTube", "campaign": "Youtube", "year": "2026"}, {"work_id": "6a5fca2e8c1e60255e2aea5b", "slug": "sealing-karmic-loops-in-rhythm-not-rush", "client": "First December Films", "campaign": "Sealing Karmic Loops in Rhythm, not Rush", "year": "2025"}]', 'Good fit for two quite different briefs. One is high volume, multi-language rollout work: a platform or app launch needing fifteen or more short films across creators, music tie-ins and trend formats, built for vertical and social, with a directing team splitting the slate and turnarounds measured in days. The other is long-form brand storytelling that runs past five minutes, voice or text led, held by ritual, observation, pacing and sound rather than plot, with modest cast and locations.', '2026-09-04T20:20:21+00:00');
INSERT OR REPLACE INTO directors (slug, name, bio, credits, strengths, indexed_at) VALUES ('atul-kattukaran', 'Atul Kattukaran', 'Atul Kattukaran is a Partner and Director at 1st December Films, and one of India''s most celebrated advertising filmmakers. A recipient of the Cannes Lions, often regarded as the Oscars of advertising, he has won in 2014, 2016, and 2017, and is the only Indian officially listed among the world''s Top 10 TVC directors by the Cannes Lions Global Creativity Report. His breakout was Nike ''Make Every Yard Count'' (2014), a four-month stop-motion odyssey featuring 1,440 young cricketers across 2,25,000 photographs, which became the most awarded film in advertising history from Asia. He then directed ''Beauty Tips by Reshma'' for Ogilvy and Make Love Not Scars, winner of the Cannes Glass Lion and Gold Lion, whose ''How to Get Perfect Red Lips'' made Adweek''s World''s Best Commercials of 2016. His work has been honoured at leading international award shows including D&amp;AD, CLIO, The One Show, Spikes Asia and Promax, as well as India''s premier advertising festivals such as Kyoorius and Goafest. Over the years he has directed campaigns for Nike, Google, Google Android, Google Pixel, Netflix × Knorr, Levi''s, KFC, Peter England, Thums Up, Oppo, Vivo, Star Sports, MuscleBlaze, Pepe Jeans, Facebook, Myntra and Unacademy, alongside the T20 World Cup 2026 campaign and the ZEE5 × FIFA promo. Most recently he received an Abby Gold for the ''Chora Chori'' campaign, Blue Elephants at the Kyoorius Awards, and a Bronze at the Good Ads Matter Awards for the Vivo X300 Pro campaign in the Artificial Intelligence, AI-Integrated Live Action Film category.', '[{"work_id": "6a5fc8e78c1e60255e2a2c2f", "slug": "vivo-x300-pro", "client": "VIVO", "campaign": "VIVO X300 PRO", "year": "2026"}, {"work_id": "6a5fc8e78c1e60255e2a2c2d", "slug": "vivo-x300", "client": "VIVO", "campaign": "VIVO X300", "year": "2026"}, {"work_id": "6a5fc7216d26e234f186585a", "slug": "malaysia-airlines", "client": "Malaysia Airlines", "campaign": "Malaysian Airlines | Cricket at 30,000 Feet", "year": "2026"}, {"work_id": "6a53d884cbeb7e4ee69acb78", "slug": "zee-x-fifa", "client": "ZEE", "campaign": "ZEE X FIFA", "year": "2026"}, {"work_id": "6a53c28ed00e55970eae7fed", "slug": "vivo", "client": "VIVO", "campaign": "Vivo X Series", "year": "2026"}, {"work_id": "6a64b36e59e34184ae1fb884", "slug": "star-sports-chora-chori", "client": "Star Sports", "campaign": "Chora Chori", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea69", "slug": "courtyard-by-marriott-2", "client": "Courtyard by Marriott", "campaign": "Courtyard by Marriott", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea67", "slug": "courtyard-by-marriott", "client": "Courtyard by Marriott", "campaign": "Courtyard by Marriott", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea65", "slug": "kfc-boneless-2", "client": "KFC", "campaign": "Pick, Pop, Dip, Strip", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea63", "slug": "kfc-boneless", "client": "KFC", "campaign": "Pick, Pop, Dip, Strip", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea5f", "slug": "campa-cola", "client": "Campa Cola", "campaign": "Campa Wali Zidd", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea59", "slug": "peter-england-viv-richards", "client": "Peter England", "campaign": "The Gentleman’s League: League of Legends", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea57", "slug": "peter-england-kapil-dev", "client": "Peter England", "campaign": "The Gentleman’s League: League of Legends", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea55", "slug": "vivo-performance", "client": "VIVO", "campaign": "VIVO : PERFORMANCE", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea53", "slug": "vivo-design", "client": "VIVO", "campaign": "VIVO : DESIGN", "year": "2025"}, {"work_id": "6a5fca2e8c1e60255e2aea51", "slug": "vivo-camera", "client": "VIVO", "campaign": "VIVO : CAMERA", "year": "2025"}, {"work_id": "